import * as array from "std/array"
import * as pages from "../pages"
import { Vec3 } from "std/vector"

// Append-only floor-plane points with immutable, paged hash chains. Source
// indices stay stable; payloads and deletion/eligibility belong to the caller.
type Point is data = #Point { x: F32, z: F32, cx: F32, cz: F32, next: U32 }
type Grid is data = #Grid { size: F32, mask: U32, heads: pages.Pages U32, points: pages.Pages Point }
const word = fn (cell: F32) => F32.to_u32 (abs cell) * 2 + (if cell < 0.0 then 1 else 0)
const bucket = fn (mask: U32) (x: F32) (z: F32) => ((word x * 73856093) ^ (word z * 19349663)) & mask
const point = fn (size: F32) (at: Vec3) (next: U32) => do:
  let cx = floor (at.x / size)
  let cz = floor (at.z / size)
  if Bool.not (is_finite cx && is_finite cz) || abs cx >= 1073741824.0 || abs cz >= 1073741824.0:
    return @panic "point grid coordinate exceeds its integer range"
  return #Point { x: at.x, z: at.z, cx, cz, next }
const build = fn (size: F32) (hint: U32) (positions: Array Vec3) => do:
  if Bool.not (is_finite size) || size <= 0.0:
    return @panic "point grid size must be positive"
  let buckets: U32 = 16
  for _ in 0 .. 16:
    if buckets >= min 1048576 hint:
      break
    buckets := self * 2
  let mask = buckets - 1
  let heads = array.fill buckets 0
  let points = array.generate positions.length (fn i => point size positions[i] 0)
  for i in 0 .. points.length:
    let p = points[i]
    let key = bucket mask p.cx p.cz
    p.next := heads[key]
    points[i] := p
    heads[key] := i + 1
  return #Grid { size, mask, heads: pages.from heads, points: pages.from points }
const push = fn (at: Vec3) (grid: Grid) => do:
  let p = point grid.size at 0
  let key = bucket grid.mask p.cx p.cz
  p.next := pages.get grid.heads key
  let index = grid.points.count
  return #Grid { size: grid.size, mask: grid.mask,
    heads: pages.set key (index + 1) grid.heads, points: pages.push p grid.points }
// Each source appears once, including hash collisions and cell boundaries.
// Order is intentionally unspecified; callers resolve ties by source index.
const within = fn (grid: Grid) (x: F32) (z: F32) (radius: F32) -> Array U32 => do:
  if Bool.not (is_finite x && is_finite z && is_finite radius) || radius < 0.0:
    return #[]
  let left = floor ((x - radius) / grid.size)
  let top = floor ((z - radius) / grid.size)
  let columns = floor ((x + radius) / grid.size) - left + 1.0
  let rows = floor ((z + radius) / grid.size) - top + 1.0
  // A broad query should cost at most a scan, not millions of empty cells.
  // Check before converting its cell extent to an integer.
  if Bool.not (is_finite columns && is_finite rows) || columns * rows > U32.to_f32 grid.points.count:
    let found = #[]
    for index in 0 .. grid.points.count:
      let p = pages.get grid.points index
      let dx = p.x - x
      let dz = p.z - z
      if dx * dx + dz * dz <= radius * radius:
        found := array.push index self
    return found
  let width = F32.to_u32 columns
  let height = F32.to_u32 rows
  let found = #[]
  for row in 0 .. height:
    let cz = top + U32.to_f32 row
    for col in 0 .. width:
      let cx = left + U32.to_f32 col
      let link = pages.get grid.heads (bucket grid.mask cx cz)
      for _ in 0 .. grid.points.count:
        if link == 0:
          break
        let index = link - 1
        let p = pages.get grid.points index
        if p.cx == cx && p.cz == cz:
          let dx = p.x - x
          let dz = p.z - z
          if dx * dx + dz * dz <= radius * radius:
            found := array.push index self
        link := p.next
  return found

sources.lib/relations.blot:
import * as array from "std/array"
import * as map from "./map"
import * as pages from "./pages"

// Typed many-to-one edges, with packed, paged incoming buckets. Forward slots
// let unlink swap-remove without searching a target's whole incoming list.
type Edge target is data = #Edge { target: target, slot: U32 }
type Relations [source, target] is data = #Relations {
  forward: map.Map [source, Edge target], inverse: map.Map [target, pages.Pages source]
}
const empty = fn () => #Relations { forward: map.empty (), inverse: map.empty () }
const target = fn source_keys source (edges: Relations [s, t]) =>
  Maybe.map (fn edge => edge.target) (map.get source_keys source edges.forward)
const sources = fn target_keys target (edges: Relations [s, t]) =>
  pages.flatten (Maybe.unwrap_or (pages.from #[]) (map.get target_keys target edges.inverse))
const fold_sources = fn target_keys target reduce initial (edges: Relations [s, t]) => do:
  let bucket = Maybe.unwrap_or (pages.from #[]) (map.get target_keys target edges.inverse)
  return pages.fold reduce initial bucket
const unlink = fn source_keys target_keys source (edges: Relations [s, t]) => do:
  let #Some edge = map.get source_keys source edges.forward else:
    return edges
  let #Some bucket = map.get target_keys edge.target edges.inverse else:
    return @panic "relationship inverse invariant"
  let last = pages.get bucket (bucket.count - 1)
  if edge.slot + 1 < bucket.count:
    edges.forward := map.set source_keys last (#Edge {target: edge.target, slot: edge.slot}) self
  let trimmed = pages.update (bucket.count - 1) #[edge.slot] (fn unused => last) bucket
  edges.forward := map.remove source_keys source self
  edges.inverse := if trimmed.count == 0 then map.remove target_keys edge.target self else map.set target_keys edge.target trimmed self
  return edges
const link = fn source_keys target_keys source destination (edges: Relations [s, t]) => do:
  if let #Some old = target source_keys source edges:
    if target_keys.equal old destination:
      return edges
  edges := unlink source_keys target_keys source edges
  let bucket = Maybe.unwrap_or (pages.from #[]) (map.get target_keys destination edges.inverse)
  edges.inverse := map.set target_keys destination (pages.push source bucket) self
  edges.forward := map.set source_keys source (#Edge {target: destination, slot: bucket.count}) self
  return edges
const remove_target = fn source_keys target_keys destination edges => do:
  for source in sources target_keys destination edges:
    edges := unlink source_keys target_keys source edges
  return edges
// Optional forest policy for same-kind keys. Reject a new cycle and also a
// pre-existing cycle encountered on the target chain; ordinary link permits cycles.
const link_acyclic = fn keys source destination (edges: Relations [k, k]) => do:
  let at = destination
  for unused in 0 .. map.count edges.forward + 1:
    if keys.equal source at:
      return #Nothing
    let #Some next = target keys at edges else:
      return #Some (link keys keys source destination edges)
    at := next
  return #Nothing

sources.lib/set.blot:
import * as map from "./map"

type Set k is data = #Set { members: map.Map [k, Unit] }
const key = map.key
const u32 = map.u32
const text = map.text
const empty = fn () => #Set { members: map.empty () }
const count = fn (values: Set k) => map.count values.members
const is_empty = fn (values: Set k) => map.is_empty values.members
const contains = fn keys key (values: Set k) => map.contains keys key values.members
const insert = fn keys key (values: Set k) => do:
  if contains keys key values:
    return values
  return #Set { members: map.set keys key () values.members }
const remove = fn keys key (values: Set k) => #Set { members: map.remove keys key values.members }
const fold = fn reduce initial (values: Set k) => map.fold (fn state key value => reduce state key) initial values.members
const values = fn (stored: Set k) => map.keys stored.members
const from = fn keys (values: Array k) => do:
  let result = empty ()
  for key in values:
    result := insert keys key self
  return result
const union = fn keys left right => fold (fn result key => insert keys key result) left right
const intersection = fn keys left right => fold (fn result key =>
  if contains keys key right then insert keys key result else result) (empty ()) left
const difference = fn keys left right => fold (fn result key => remove keys key result) left right
const is_subset = fn keys left right => fold (fn result key => result && contains keys key right) #True left
const equal = fn keys left right => count left == count right && is_subset keys left right

sources.lib/ecs.blot:
import * as array from "std/array"
import * as changes from "./changes"
import * as journal from "./journal"
import * as messages from "./messages"

type Builder [world, scope, checkpoint, schema] is data = #Builder { initial: world, scope: world -> scope, checkpoint: checkpoint, schema: schema }
type Simulation [world, scope, checkpoint] is data = #Simulation { initial: world, scope: world -> scope, checkpoint: checkpoint }
type End is data = #End
type Entry { head, tail } is data = #Entry { head, tail }
// A column keeps its entities' components in leaves of 32 slots, gathered 16
// leaves to a block. A scoped `set` or `remove` copies one leaf, its block and
// the list of blocks. The arrays they still share are small: releasing a
// shared array queues it for the cycle collector, which then revisits it.
type Column component is data = #Column { revision: U32, structure: U32, journal: Maybe journal.Journal, values: Array (Array (Array (Maybe component))), masks: Array U32, occupied: Array U32 }
type Snapshot value is data = #Snapshot value
// An immutable column snapshot. Reads allocate no whole entity-sized array.
type ReadView component is data = #ReadView { count: U32, bits: Array U32, values: Array (Array (Array (Maybe component))), masks: Array U32, occupied: Array U32 }
// How many entities there have been, and a bit per entity, 32 to a word,
// set while it is alive. Bits past the count are clear.
type Entities is data = #Entities { revision: U32, count: U32, bits: Array U32, occupied: Array U32 }
// The scoped entity, or `no_entity` outside any scope: a plain U32 needs no
// Maybe of its own each time a scope is entered.
type Entity is data = #Entity U32

// Registry maintenance forwards through every registered component provider.
// Resources are untouched; applications explicitly remap entity references.
type Maintenance is effect = { remove: U32 -> Unit, remap: Array U32 -> Unit }
type Remap is data = #Remap { previous: Array U32, current: Array U32 }

type State a is effect = {
  get: Unit -> a
  set: a -> Unit
}

const End.contains = fn (end: End) => fn witness => #False

const Entry.contains = fn entry => fn witness => do:
  let #Entry { head, tail } = entry
  if :head == :witness:
    return #True
  return tail.contains(witness)

const get = fn (witness: p -> a) -> a => State.get ()
const set = fn value => State.set value

// Builders are rebuilt field by field: a path update such as
// `builder.initial := (value, self)` changes the builder's type, and blotc
// crashes when such a generic helper is applied twice.
const empty = fn () => do:
  let scope = fn world => fn action => do:
    use result <- do (@effect.provider Maintenance.remove (fn (index: U32) => ())):
      use value <- do (@effect.provider Maintenance.remap (fn (indices: Array U32) => ())):
        use answer <- action ()
        break answer
      break value
    return (world, result)
  return #Builder { initial: (), scope, checkpoint: fn () => (), schema: #End }

const insert_cell = fn (initial: cell) => fn (builder: Builder [previous, scope, checkpoint, schema]) => do:
  let #Builder { initial: previous_initial, scope: previous_scope, checkpoint, schema } = builder
  let scope = fn (world: (cell, previous)) => fn action => do:
    let (current, previous) = world
    use outcome <- @effect.run State.get State.set current (fn () => previous_scope previous action)
    let (next, (previous_next, result)) = outcome
    return ((next, previous_next), result)
  return #Builder { initial: (initial, previous_initial), scope, checkpoint, schema }

// An opt-in semantic revision, checked at the write boundary. Revision keys
// belong to this immutable world and its caches; do not compare keys from
// independent/forked worlds. Restored worlds and their caches start afresh.
type Observed value is data = #Observed { value: value, revision: U32 }
const revision = fn (exemplar: value) => do:
  use cell <- get (fn () => #Observed { value: exemplar, revision: 0 })
  return cell.revision
const insert_observed_cell = fn equal => fn initial => fn builder => do:
  let #Builder { initial: world, scope, checkpoint, schema } = insert_cell (#Observed { value: initial, revision: 0 }) builder
  let read = fn () => do:
    use cell <- get (fn () => #Observed { value: initial, revision: 0 })
    return cell.value
  let write = fn value => do:
    use cell <- get (fn () => #Observed { value: initial, revision: 0 })
    if Bool.not (equal cell.value value):
      if cell.revision == 4294967295:
        return @panic "ECS semantic revision exhausted"
      cell.revision := self + 1
    cell.value := value
    return set cell
  let observed = fn world => fn action => scope world (fn () =>
    @effect.reader State.get initial read (fn () =>
      @effect.writer State.set initial write action))
  return #Builder { initial: world, scope: observed, checkpoint, schema }

const insert_snapshotted = fn initial => fn builder => do:
  let #Builder { checkpoint: previous_checkpoint } = builder
  builder := insert_cell initial self
  builder := insert_cell (#Snapshot initial) self
  let #Builder { initial: initial_world, scope, schema } = builder
  let checkpoint = fn () => do:
    use previous_checkpoint ()
    use current <- get (fn () => initial)
    use set (#Snapshot current)
  return #Builder { initial: initial_world, scope, checkpoint, schema }

const insert_resource = fn value => fn builder => do:
  let #Builder { schema } = builder
  if schema.contains(value):
    return @panic "resource type already initialized"
  let #Builder { initial, scope, checkpoint } = insert_cell value builder
  return #Builder { initial, scope, checkpoint, schema: #Entry { head: value, tail: schema } }

const insert_observed_resource = fn equal => fn value => fn builder => do:
  let #Builder { schema } = builder
  if schema.contains(value):
    return @panic "resource type already initialized"
  let #Builder { initial, scope, checkpoint } = insert_observed_cell equal value builder
  return #Builder { initial, scope, checkpoint, schema: #Entry { head: value, tail: schema } }

// An explicit observed write carries the caller's semantic change witness.
// Available only for observed resources. The caller must preserve any derived
// state and set changed exactly when the registered equality would be false.
// Ordinary replacement writes retain their preparation and equality checks.
const write_observed = fn changed => fn value => do:
  use cell <- get (fn () => #Observed { value, revision: 0 })
  if changed:
    if cell.revision == 0xFFFFFFFF:
      return @panic "ECS semantic revision exhausted"
    cell.revision := self + 1
  cell.value := value
  return set cell
const insert_observed_resource_using = fn (prepare: resource -> resource -> resource) => fn (equal: resource -> resource -> Bool) => fn (value: resource) => fn builder => do:
  let #Builder { schema } = builder
  if schema.contains(value):
    return @panic "resource type already initialized"
  let #Builder { initial, scope, checkpoint } = insert_cell (#Observed { value, revision: 0 }) builder
  let read = fn () => do:
    use cell <- get (fn () => #Observed { value, revision: 0 })
    return cell.value
  let write = fn incoming => do:
    use cell <- get (fn () => #Observed { value, revision: 0 })
    let next = prepare cell.value incoming
    if Bool.not (equal cell.value next):
      if cell.revision == 0xFFFFFFFF:
        return @panic "ECS semantic revision exhausted"
      cell.revision := self + 1
    cell.value := next
    return set cell
  let observed = fn world => fn action => scope world (fn () =>
    @effect.reader State.get value read (fn () =>
      @effect.writer State.set value write action))
  return #Builder { initial, scope: observed, checkpoint, schema: #Entry { head: value, tail: schema } }

// Snapshotted resources and components also keep their value from the last
// checkpoint, readable through `previous` and `previous_components`.
const insert_snapshotted_resource = fn value => fn builder => do:
  let #Builder { schema } = builder
  if schema.contains(value):
    return @panic "resource type already initialized"
  let #Builder { initial, scope, checkpoint } = insert_snapshotted value builder
  return #Builder { initial, scope, checkpoint, schema: #Entry { head: value, tail: schema } }

// Spawning stops before this count, so no entity has it.
const no_entity = 4294967295

const new = fn () => do:
  let builder = empty ()
  builder := insert_cell #Entities { revision: 0, count: 0, bits: #[], occupied: #[] } self
  builder := insert_cell (#Entity no_entity) self
  return builder

// Revisions belong to one immutable world. A cache must be kept in that world
// and reset with it; independent forks can have equal revision numbers.
const bumped_revision = fn (before: U32) => do:
  if before == 4294967295:
    return @panic "ECS revision exhausted"
  return before + 1
const membership_revision = fn () => do:
  use current <- get #Entities
  return current.revision
const component_revision = fn (constructor: p -> a) => do:
  use column <- get (fn payload => make_column #[#[#[#Some (constructor payload)]]])
  return column.revision

// The 32-bit words holding `count` bits.
const words = fn (count: U32) => do:
  let full = count >> 5
  if count & 31 != 0:
    return full + 1
  return full

const live = fn (bits: Array U32) => fn (selected: U32) => (bits[selected >> 5] >> (selected & 31)) & 1 != 0

// The low `count` bits of a word set, for count up to 32.
const low_bits = fn (count: U32) => do:
  if count >= 32:
    return 0xFFFFFFFF
  return (1 << count) - 1

// Every entity's alive flag, indexed by entity.
const entities = fn () => do:
  use current <- get #Entities
  let #Entities { count, bits } = current
  return array.generate count (fn selected => live bits selected)

const replace_entities = fn (alive: Array Bool) => do:
  use current <- get #Entities
  let count = alive.length
  let bits = array.generate (words count) (fn word => do:
    let start = word << 5
    let packed = 0
    for offset in 0 .. 32:
      let selected = start + offset
      if selected < count:
        if alive[selected]:
          packed := self | (1 << offset)
    return packed)
  return set #Entities { revision: bumped_revision current.revision, count, bits, occupied: occupied_words bits }

// Entity `selected`, checked to be alive.
const existing = fn (selected: U32) => do:
  use current <- get #Entities
  let #Entities { count, bits } = current
  if selected >= count:
    return @panic "entity is outside the world"
  if Bool.not (live bits selected):
    return @panic "entity has been removed"
  return selected

// The scoped entity lives in the world rather than in a provider: component
// readers run in their own scope, outside any provider a system installs.
const entity = fn () => do:
  use current_entity <- get #Entity
  let #Entity selected = current_entity
  if selected == no_entity:
    return @panic "component access requires an entity scope"
  return existing selected

const leaf_bits = 5
const leaf_size = 32
const leaf_mask = 31
const branch_bits = 4
const branch_mask = 15
const block_leaves = 16
const block_bits = 9
const block_slots = 512

// How many units of `1 << bits` cover `count`.
const units = fn (count: U32) => fn (bits: U32) => do:
  let whole = count >> bits
  if count & ((1 << bits) - 1) != 0:
    return whole + 1
  return whole

// Bounds-checked indexing rather than `values.get`, through which each read
// made cycle-collector work grow with the make_column (see docs/blot.md).
const component_at = fn blocks => fn selected => do:
  let block = selected >> block_bits
  if block < blocks.length:
    let leaves = blocks[block]
    let leaf = (selected >> leaf_bits) & branch_mask
    if leaf < leaves.length:
      let slots = leaves[leaf]
      let slot = selected & leaf_mask
      if slot < slots.length:
        return slots[slot]
  return #Nothing

// A column of `count` slots, `slot_at` giving each; the last leaf pads with
// Nothing and the last block holds only the leaves it needs.
const chunked = fn (count: U32) => fn slot_at => do:
  let leaves = units count leaf_bits
  return array.generate (units leaves branch_bits) (fn block => do:
    let first_leaf = block << branch_bits
    return array.generate (min block_leaves (leaves - first_leaf)) (fn leaf => do:
      let start = (first_leaf + leaf) << leaf_bits
      return array.generate leaf_size (fn slot => do:
        let selected = start + slot
        if selected < count:
          return slot_at selected
        return #Nothing)))

// `values` as a column: whole leaves are sliced out, the last one padded.
const chunks_of = fn (values: Array (Maybe a)) => do:
  let count = values.length
  let leaves = units count leaf_bits
  return array.generate (units leaves branch_bits) (fn block => do:
    let first_leaf = block << branch_bits
    return array.generate (min block_leaves (leaves - first_leaf)) (fn leaf => do:
      let start = (first_leaf + leaf) << leaf_bits
      if count - start >= leaf_size:
        return array.slice start leaf_size values
      return array.generate leaf_size (fn slot => do:
        let selected = start + slot
        if selected < count:
          return values[selected]
        return #Nothing)))

// `leaves` grown to reach leaf `leaf`, whose slot `slot` holds `entry`.
const grown_block = fn leaves => fn (leaf: U32) => fn (slot: U32) => fn entry =>
  array.generate (leaf + 1) (fn index => do:
    if index < leaves.length:
      return leaves[index]
    return array.generate leaf_size (fn at => do:
      if index == leaf && at == slot:
        return entry
      return #Nothing))

// `blocks` with slot `selected` holding `entry`: one leaf, its block and the
// list of blocks are copied, growing to reach the slot.
const placed = fn blocks => fn (selected: U32) => fn entry => do:
  let block = selected >> block_bits
  let leaf = (selected >> leaf_bits) & branch_mask
  let slot = selected & leaf_mask
  if block < blocks.length:
    let leaves = blocks[block]
    if leaf < leaves.length:
      let slots = leaves[leaf]
      slots[slot] := entry
      leaves[leaf] := slots
      blocks[block] := leaves
      return blocks
    blocks[block] := grown_block leaves leaf slot entry
    return blocks
  let none = array.generate 0 (fn index => array.fill leaf_size entry)
  return array.generate (block + 1) (fn index => do:
    if index < blocks.length:
      return blocks[index]
    if index == block:
      return grown_block none leaf slot entry
    return none)

// Sorted active word indices are snapshot values, updated only on membership changes.
const occupied_words = fn (masks: Array U32) -> Array U32 => do:
  let count = 0
  for mask in masks:
    if mask != 0:
      count := self + 1
  let occupied = array.fill count 0
  let at = 0
  for word in 0 .. masks.length:
    if masks[word] != 0:
      occupied[at] := word
      at := self + 1
  return occupied
const membership = fn (word: U32) => fn (present: Bool) => fn (before: Array U32) => do:
  let low = 0
  let high = before.length
  for 0 .. 32:
    if low >= high:
      break
    let middle = low + (high - low) / 2
    if before[middle] < word:
      low := middle + 1
    else:
      high := middle
  let exists = low < before.length && before[low] == word
  if exists:
    if present:
      return before
    return array.generate (before.length - 1) (fn i => before[if i < low then i else i + 1])
  if Bool.not present:
    return before
  return array.generate (before.length + 1) (fn i => if i < low then before[i] else if i == low then word else before[i - 1])
const occupied_range = fn before => fn (first: U32) => fn (count: U32) => do:
  if count == 0:
    return before
  let start = first >> 5
  let end = ((first + count - 1) >> 5) + 1
  let included = before.length > 0 && before[before.length - 1] == start
  let next = if included then start + 1 else start
  return array.generate (before.length + end - next) (fn i => if i < before.length then before[i] else next + i - before.length)
const word_mask = fn (masks: Array U32) => fn (word: U32) => if word < masks.length then masks[word] else 0
const make_column = fn (values: Array (Array (Array (Maybe a)))) => do:
  let masks = array.generate (values.length * block_leaves) (fn word => do:
    let leaves = values[word >> branch_bits]
    let leaf = word & branch_mask
    if leaf >= leaves.length:
      return 0
    let slots = leaves[leaf]
    let mask = 0
    for slot in 0 .. slots.length:
      if Maybe.is_some slots[slot]:
        mask := self | (1 << slot)
    return mask)
  return #Column { revision: 0, structure: 0, journal: #Nothing, values, masks, occupied: occupied_words masks }
const place = fn (before: Column a) => fn (selected: U32) => fn (entry: Maybe a) => do:
  let word = selected >> leaf_bits
  let old = word_mask before.masks word
  let bit = 1 << (selected & leaf_mask)
  let mask = if Maybe.is_some entry then old | bit else old & (0xFFFFFFFF ^ bit)
  let masks = before.masks
  if word >= masks.length:
    masks := array.generate (word + 1) (fn i => word_mask before.masks i)
  masks[word] := mask
  let next = before
  next.values := placed before.values selected entry
  next.masks := masks
  next.occupied := membership word (mask != 0) before.occupied
  return changed_column before next #[selected]

const read_component = fn (exemplar: a) => fn () => do:
  use selected <- entity ()
  use column <- get (fn () => make_column #[#[#[#Some exemplar]]])
  let #Column { values: values } = column
  let #Some value = component_at values selected else:
    return @panic "entity does not have the requested component"
  return value

const write_component = fn (value: a) => do:
  use selected <- entity ()
  use column <- get (fn () => make_column #[#[#[#Some value]]])
  let #Column { values: chunks } = column
  return set (place column selected (#Some value))

const read_previous_component = fn (exemplar: a) => fn () => do:
  use selected <- entity ()
  use stored <- get (fn () => #Snapshot (make_column #[#[#[#Some exemplar]]]))
  let #Snapshot (#Column { values: previous }) = stored
  if let #Some value = component_at previous selected:
    return #Snapshot value
  use current <- read_component exemplar ()
  return #Snapshot current

const retire_component = fn (exemplar: a) (selected: U32) => do:
  use column <- get (fn () => make_column #[#[#[#Some exemplar]]])
  if Maybe.is_some (component_at column.values selected):
    use set (place column selected #Nothing)
  return Maintenance.remove selected
const remap_component = fn (exemplar: a) (indices: Array U32) => do:
  use column <- get (fn () => make_column #[#[#[#Some exemplar]]])
  use replace_column (make_column (chunks_of (array.map (fn index => component_at column.values index) indices)))
  return Maintenance.remap indices
const remap_snapshotted_component = fn (exemplar: a) (indices: Array U32) => do:
  use previous <- get (fn () => #Snapshot (make_column #[#[#[#Some exemplar]]]))
  let #Snapshot old = previous
  use set (#Snapshot (make_column (chunks_of (array.map (fn index => component_at old.values index) indices))))
  return remap_component exemplar indices
const maintaining = fn exemplar remap action => do (@effect.provider Maintenance.remove (retire_component exemplar)):
  use result <- do (@effect.provider Maintenance.remap remap):
    use value <- action ()
    break value
  break result

const register_component_with = fn tracking => fn exemplar => fn builder => do:
  let #Builder { schema } = builder
  if schema.contains(exemplar):
    return @panic "component type already registered"
  let initial_column = make_column (array.generate 0 (fn index => #[#[#Some exemplar]]))
  initial_column.journal := tracking
  let #Builder { initial, scope, checkpoint } = insert_cell initial_column builder
  let next_scope = fn world => fn action => scope world (fn () =>
    @effect.reader State.get exemplar (read_component exemplar) (fn () =>
      @effect.writer State.set exemplar write_component (fn () => maintaining exemplar (remap_component exemplar) action)))
  return #Builder { initial, scope: next_scope, checkpoint, schema: #Entry { head: exemplar, tail: schema } }

const register_snapshotted_component_with = fn tracking => fn exemplar => fn builder => do:
  let #Builder { schema } = builder
  if schema.contains(exemplar):
    return @panic "component type already registered"
  let initial_column = make_column (array.generate 0 (fn index => #[#[#Some exemplar]]))
  initial_column.journal := tracking
  let #Builder { initial, scope, checkpoint } = insert_snapshotted initial_column builder
  let next_scope = fn world => fn action => scope world (fn () =>
    @effect.reader State.get (#Snapshot exemplar) (read_previous_component exemplar) (fn () =>
      @effect.reader State.get exemplar (read_component exemplar) (fn () =>
        @effect.writer State.set exemplar write_component (fn () => maintaining exemplar (remap_snapshotted_component exemplar) action))))
  return #Builder { initial, scope: next_scope, checkpoint, schema: #Entry { head: exemplar, tail: schema } }

const register_component = fn exemplar builder => register_component_with #Nothing exemplar builder
const register_snapshotted_component = fn exemplar builder => register_snapshotted_component_with #Nothing exemplar builder
const register_tracked_component = fn epoch capacity exemplar builder => register_component_with (#Some (journal.empty epoch capacity)) exemplar builder
const register_tracked_snapshotted_component = fn epoch capacity exemplar builder => register_snapshotted_component_with (#Some (journal.empty epoch capacity)) exemplar builder

const add_plugin = fn plugin => fn builder => plugin builder

const build = fn builder => do:
  let #Builder { initial, scope, checkpoint } = builder
  return #Simulation { initial, scope, checkpoint }

const run = fn simulation => fn world => fn action => do:
  let #Simulation { scope } = simulation
  return scope world action

const create = fn simulation => fn action => do:
  let #Simulation { initial } = simulation
  return run simulation initial action

const checkpoint = fn simulation => do:
  let #Simulation { checkpoint } = simulation
  return checkpoint ()

const replace_previous = fn value => set (#Snapshot value)

const previous = fn constructor => do:
  use stored <- get (fn payload => #Snapshot (constructor payload))
  let #Snapshot value = stored
  return value

// Runs `action` scoped to entity `selected`, so component `get` and `set`
// address it. Scopes nest; the outer one is restored afterwards.
const at = fn selected => fn action => do:
  use existing selected
  use previous <- get #Entity
  use set (#Entity selected)
  use result <- action ()
  use set previous
  return result

// `bits` with `count` more live entities after the first `existing`.
const grown = fn (bits: Array U32) => fn (existing: U32) => fn (count: U32) => do:
  let total = existing + count
  return array.generate (words total) (fn word => do:
    let start = word << 5
    let kept = if word < bits.length then bits[word] else 0
    let low = if existing > start then existing - start else 0
    let high = if total > start then total - start else 0
    return kept | (low_bits high & (0xFFFFFFFF ^ low_bits low)))

const spawn = fn action => do:
  use current <- get #Entities
  let #Entities { count, bits, occupied } = current
  if count == 4294967295:
    return @panic "entity count overflow"
  use set #Entities { revision: bumped_revision current.revision, count: count + 1, bits: grown bits count 1, occupied: occupied_range occupied count 1 }
  use at count action
  return count

// Adds `count` live entities at once, without components, and returns the
// first one. Give them components with `insert_many`.
const spawn_many = fn (count: U32) => do:
  use current <- get #Entities
  let #Entities { count: first, bits, occupied } = current
  if count > 4294967295 - first:
    return @panic "entity count overflow"
  use set #Entities { revision: bumped_revision current.revision, count: first + count, bits: grown bits first count, occupied: occupied_range occupied first count }
  return first

// Gives entity `first + index` the component `values[index]`, writing the
// column once rather than once per entity.
const insert_many = fn (constructor: p -> a) => fn (first: U32) => fn (values: Array a) => do:
  use current <- get #Entities
  let #Entities { count, bits } = current
  if first > count || values.length > count - first:
    return @panic "component range is outside the world"
  for selected in first .. first + values.length:
    if Bool.not (live bits selected):
      return @panic "component range contains a removed entity"
  use column <- get (fn payload => make_column #[#[#[#Some (constructor payload)]]])
  let #Column { values: stored } = column
  let end = first + values.length
  let leaves = units end leaf_bits
  // Blocks and leaves outside the range are kept as they are.
  return replace_column (make_column (array.generate (max stored.length (units leaves branch_bits)) (fn block => do:
    let start = block << block_bits
    if block < stored.length && (start >= end || (first > start && first - start >= block_slots)):
      return stored[block]
    let kept = if block < stored.length then stored[block] else array.generate 0 (fn index => array.generate leaf_size (fn slot => component_at stored slot))
    let first_leaf = block << branch_bits
    let needed = if leaves > first_leaf then min block_leaves (leaves - first_leaf) else 0
    return array.generate (max kept.length needed) (fn leaf => do:
      let leaf_start = start + (leaf << leaf_bits)
      if leaf < kept.length && (leaf_start >= end || (first > leaf_start && first - leaf_start >= leaf_size)):
        return kept[leaf]
      return array.generate leaf_size (fn slot => do:
        let index = leaf_start + slot
        if index >= first && index < end:
          return #Some values[index - first]
        return component_at stored index)))))

const despawn = fn selected => do:
  use current <- get #Entities
  let #Entities { count, bits, occupied } = current
  if selected >= count:
    return @panic "entity is outside the world"
  if Bool.not (live bits selected):
    return ()
  use Maintenance.remove selected
  let word = selected >> 5
  bits[word] := self & (0xFFFFFFFF ^ (1 << (selected & 31)))
  use set #Entities { revision: bumped_revision current.revision, count, bits, occupied: membership word (bits[word] != 0) occupied }

const alive = fn selected => do:
  use current <- get #Entities
  let #Entities { count, bits } = current
  if selected < count:
    return live bits selected
  return #False

const remove = fn (constructor: p -> a) => do:
  use selected <- entity ()
  use column <- get (fn payload => make_column #[#[#[#Some (constructor payload)]]])
  let #Column { values: blocks } = column
  if Maybe.is_some (component_at blocks selected):
    use set (place column selected #Nothing)

// Every live entity's component, or Nothing, indexed by entity.
const components = fn constructor => do:
  use current <- get #Entities
  let #Entities { count, bits } = current
  use column <- get (fn payload => make_column #[#[#[#Some (constructor payload)]]])
  let #Column { values: values } = column
  return array.generate count (fn selected => do:
    if live bits selected:
      return component_at values selected
    return #Nothing)

// The values of the entries that have one, counted and then copied into an
// array of that length.
const somes = fn (entries: Array (Maybe a)) => do:
  let found = 0
  let seed = #Nothing
  for entry in entries:
    if Maybe.is_some entry:
      if found == 0:
        seed := entry
      found := self + 1
  let #Some first = seed else:
    return #[]
  let values = array.fill found first
  let at = 0
  for entry in entries:
    if let #Some value = entry:
      values[at] := value
      at := self + 1
  return values

// A view remains a snapshot when the world is subsequently edited.
const view = fn constructor => do:
  use current <- get #Entities
  let #Entities { count, bits } = current
  use column <- get (fn payload => make_column #[#[#[#Some (constructor payload)]]])
  let #Column { values, masks, occupied: components } = column
  let #Entities { occupied: entities } = current
  return #ReadView { count, bits, values, masks, occupied: if entities.length < components.length then entities else components }
const previous_view = fn constructor => do:
  use current <- get #Entities
  let #Entities { count, bits } = current
  use stored <- get (fn payload => #Snapshot (make_column #[#[#[#Some (constructor payload)]]]))
  let #Snapshot (#Column { values, masks, occupied: components }) = stored
  let #Entities { occupied: entities } = current
  return #ReadView { count, bits, values, masks, occupied: if entities.length < components.length then entities else components }
const read = fn (view: ReadView a) => fn (selected: U32) => do:
  if selected < view.count:
    if live view.bits selected:
      return component_at view.values selected
  return #Nothing

// Count and copy present components directly from the column. Do not first
// build every entity's optional slot, especially for sparse columns.
const present = fn constructor => do:
  use source <- view constructor
  let found = 0
  let seed = #Nothing
  for word in source.occupied:
    let mask = word_mask source.bits word & word_mask source.masks word
    for slot in 0 .. leaf_size:
      if (mask >> slot) & 1 != 0:
        let #Some value = component_at source.values ((word << leaf_bits) + slot) else:
          return @panic "component membership invariant"
        if found == 0:
          seed := #Some value
        found := self + 1
  let #Some first = seed else:
    return #[]
  let values = array.fill found first
  let at = 0
  for word in source.occupied:
    let mask = word_mask source.bits word & word_mask source.masks word
    for slot in 0 .. leaf_size:
      if (mask >> slot) & 1 != 0:
        let #Some value = component_at source.values ((word << leaf_bits) + slot) else:
          return @panic "component membership invariant"
        values[at] := value
        at := self + 1
  return values

// All whole-column writers share this boundary, including restore and bulk
// updates. Per-entity writes increment in `place` without rereading the column.
const replace_column = fn next => do:
  use before <- get (fn () => next)
  next.revision := bumped_revision before.revision
  let structural = #False
  for word in 0 .. max before.masks.length next.masks.length:
    if word_mask before.masks word != word_mask next.masks word:
      structural := #True
      break
  next.structure := if structural then bumped_revision before.structure else before.structure
  next.journal := Maybe.map (journal.record #journal.Replaced) before.journal
  return set next

const replace_components = fn (constructor: p -> a) => fn (values: Array (Maybe a)) =>
  replace_column (make_column (chunks_of values))

// Entity `selected`'s component, if it is alive and has one: one cell, where
// `components` builds the whole column.
const component_of = fn constructor => fn (selected: U32) => do:
  use current <- get #Entities
  let #Entities { count, bits } = current
  use column <- get (fn payload => make_column #[#[#[#Some (constructor payload)]]])
  let #Column { values: values } = column
  if selected >= count:
    return #Nothing
  if live bits selected:
    return component_at values selected
  return #Nothing

// Its snapshotted component's value from the previous fixed step, if any.
const previous_component_of = fn constructor => fn (selected: U32) => do:
  use current <- get #Entities
  let #Entities { count, bits } = current
  use stored <- get (fn payload => #Snapshot (make_column #[#[#[#Some (constructor payload)]]]))
  let #Snapshot (#Column { values: previous }) = stored
  if selected >= count:
    return #Nothing
  if live bits selected:
    return component_at previous selected
  return #Nothing

const previous_components = fn constructor => do:
  use current <- get #Entities
  let #Entities { count, bits } = current
  use stored <- get (fn payload => #Snapshot (make_column #[#[#[#Some (constructor payload)]]]))
  let #Snapshot (#Column { values: previous }) = stored
  return array.generate count (fn selected => do:
    if live bits selected:
      return component_at previous selected
    return #Nothing)

const replace_previous_components = fn (constructor: p -> a) => fn (values: Array (Maybe a)) =>
  set (#Snapshot (make_column (chunks_of values)))

// Column-wise systems. Each replaces the components of every live entity that
// has all the named ones with what pure `step` returns, and writes each column
// once. Entities missing one keep theirs. Use these for work across many
// entities: a scoped `set`, as in `query`, copies a leaf and a block.
const update = fn (constructor: p -> a) => fn step => do:
  use current <- get #Entities
  let #Entities { count, bits } = current
  use column <- get (fn payload => make_column #[#[#[#Some (constructor payload)]]])
  let #Column { values: chunks } = column
  return replace_column (make_column (chunked count (fn selected => do:
    if live bits selected:
      return Maybe.map step (component_at chunks selected)
    return #Nothing)))

const stepped_pair = fn step => fn first => fn second => case first, second of
  #Some a, #Some b => do:
    let (next_a, next_b) = step a b
    break (#Some next_a, #Some next_b)
  a, b => (a, b)

const update_pair = fn (left: p -> a) => fn (right: q -> b) => fn step => do:
  use current <- get #Entities
  let #Entities { count, bits } = current
  use left_column <- get (fn payload => make_column #[#[#[#Some (left payload)]]])
  use right_column <- get (fn payload => make_column #[#[#[#Some (right payload)]]])
  let #Column { values: lefts } = left_column
  let #Column { values: rights } = right_column
  let leaves = units count leaf_bits
  let results = array.generate leaves (fn leaf => do:
    let start = leaf << leaf_bits
    let present = fn source => fn slot => do:
      let index = start + slot
      if index < count:
        if live bits index:
          return component_at source index
      return #Nothing
    let next_left = array.generate leaf_size (present lefts)
    let next_right = array.generate leaf_size (present rights)
    for slot in 0 .. min leaf_size (count - start):
      if let #Some a = next_left[slot]:
        if let #Some b = next_right[slot]:
          let (next_a, next_b) = step a b
          next_left[slot] := #Some next_a
          next_right[slot] := #Some next_b
    return (next_left, next_right))
  let grouped = fn selected => array.generate (units leaves branch_bits) (fn block => do:
    let first_leaf = block << branch_bits
    return array.generate (min block_leaves (leaves - first_leaf)) (fn leaf => selected results[first_leaf + leaf]))
  use replace_column (make_column (grouped (fn pair => do:
    let (next, _) = pair
    return next)))
  return replace_column (make_column (grouped (fn pair => do:
    let (_, next) = pair
    return next)))

const update_triple = fn (first: p -> a) => fn (second: q -> b) => fn (third: r -> c) => fn step =>
  update_triple_indexed first second third (fn index => step)

const stepped_triple = fn step => fn index => fn first => fn second => fn third => case first, second, third of
  #Some a, #Some b, #Some c => do:
    let (next_a, next_b, next_c) = step index a b c
    break (#Some next_a, #Some next_b, #Some next_c)
  a, b, c => (a, b, c)

// `update_triple` whose step also receives the entity.
const update_triple_indexed = fn (first: p -> a) => fn (second: q -> b) => fn (third: r -> c) => fn step => do:
  use current <- get #Entities
  let #Entities { count, bits } = current
  use first_column <- get (fn payload => make_column #[#[#[#Some (first payload)]]])
  use second_column <- get (fn payload => make_column #[#[#[#Some (second payload)]]])
  use third_column <- get (fn payload => make_column #[#[#[#Some (third payload)]]])
  let #Column { values: firsts } = first_column
  let #Column { values: seconds } = second_column
  let #Column { values: thirds } = third_column
  let leaves = units count leaf_bits
  let results = array.generate leaves (fn leaf => do:
    let start = leaf << leaf_bits
    let present = fn source => fn slot => do:
      let index = start + slot
      if index < count:
        if live bits index:
          return component_at source index
      return #Nothing
    let next_first = array.generate leaf_size (present firsts)
    let next_second = array.generate leaf_size (present seconds)
    let next_third = array.generate leaf_size (present thirds)
    for slot in 0 .. min leaf_size (count - start):
      if let #Some a = next_first[slot]:
        if let #Some b = next_second[slot]:
          if let #Some c = next_third[slot]:
            let (next_a, next_b, next_c) = step (start + slot) a b c
            next_first[slot] := #Some next_a
            next_second[slot] := #Some next_b
            next_third[slot] := #Some next_c
    return (next_first, next_second, next_third))
  let grouped = fn selected => array.generate (units leaves branch_bits) (fn block => do:
    let first_leaf = block << branch_bits
    return array.generate (min block_leaves (leaves - first_leaf)) (fn leaf => selected results[first_leaf + leaf]))
  use replace_column (make_column (grouped (fn triple => do:
    let (next, _, _) = triple
    return next)))
  use replace_column (make_column (grouped (fn triple => do:
    let (_, next, _) = triple
    return next)))
  return replace_column (make_column (grouped (fn triple => do:
    let (_, _, next) = triple
    return next)))

// Batched writes copy each selected leaf/block once. Selected slots must be
// sorted, unique and already present. Membership and old snapshots are kept.
const patched_column = fn (column: Column a) => fn (selected: Array U32) => fn value => do:
  let blocks = array.generate column.values.length (fn i => column.values[i])
  for first in 0 .. selected.length:
    let block = selected[first] >> block_bits
    if first == 0 || selected[first - 1] >> block_bits != block:
      let leaves = array.generate blocks[block].length (fn i => column.values[block][i])
      for at in first .. selected.length:
        if selected[at] >> block_bits != block:
          break
        let word = selected[at] >> leaf_bits
        if at == first || selected[at - 1] >> leaf_bits != word:
          let leaf = word & branch_mask
          let slots = array.generate leaf_size (fn i => column.values[block][leaf][i])
          for index in at .. selected.length:
            if selected[index] >> leaf_bits != word:
              break
            slots[selected[index] & leaf_mask] := #Some (value index)
          leaves[leaf] := slots
      blocks[block] := leaves
  column.values := blocks
  return column

const matching_selected = fn (current: Entities) (requested: Array U32) matches => do:
  let requested = changes.unique requested
  let selected = array.fill requested.length 0
  let count = 0
  for index in requested:
    if index < current.count:
      if live current.bits index:
        if matches index:
          selected[count] := index
          count := self + 1
  return array.slice 0 count selected

// Call step once per selected live entity, in ascending entity order. Missing
// components, repeated IDs and out-of-range IDs are ignored. Empty selections
// do not write columns or advance revisions.
const update_selected = fn (constructor: p -> a) => fn requested => fn step => do:
  use current <- get #Entities
  use column <- get (fn payload => make_column #[#[#[#Some (constructor payload)]]])
  let selected = matching_selected current requested (fn i => (word_mask column.masks (i >> leaf_bits) >> (i & leaf_mask)) & 1 != 0)
  if selected.length == 0:
    return ()
  return replace_selected selected (patched_column column selected (fn at => do:
    let index = selected[at]
    let #Some value = component_at column.values index else:
      return @panic "component membership invariant"
    return step index value))

const update_pair_selected = fn (left: p -> a) => fn (right: q -> b) => fn requested => fn step => do:
  use current <- get #Entities
  use a <- get (fn payload => make_column #[#[#[#Some (left payload)]]])
  use b <- get (fn payload => make_column #[#[#[#Some (right payload)]]])
  let selected = matching_selected current requested (fn i =>
    ((word_mask a.masks (i >> leaf_bits) & word_mask b.masks (i >> leaf_bits)) >> (i & leaf_mask)) & 1 != 0)
  if selected.length == 0:
    return ()
  let values = array.map (fn i => do:
    let #Some x = component_at a.values i else:
      return @panic "component membership invariant"
    let #Some y = component_at b.values i else:
      return @panic "component membership invariant"
    return step i x y) selected
  use replace_selected selected (patched_column a selected (fn at => do:
    let (x, _) = values[at]
    return x))
  return replace_selected selected (patched_column b selected (fn at => do:
    let (_, y) = values[at]
    return y))

const update_triple_selected = fn (first: p -> a) => fn (second: q -> b) => fn (third: r -> c) => fn requested => fn step => do:
  use current <- get #Entities
  use a <- get (fn payload => make_column #[#[#[#Some (first payload)]]])
  use b <- get (fn payload => make_column #[#[#[#Some (second payload)]]])
  use c <- get (fn payload => make_column #[#[#[#Some (third payload)]]])
  let selected = matching_selected current requested (fn i =>
    ((word_mask a.masks (i >> leaf_bits) & word_mask b.masks (i >> leaf_bits) & word_mask c.masks (i >> leaf_bits)) >> (i & leaf_mask)) & 1 != 0)
  if selected.length == 0:
    return ()
  let values = array.map (fn i => do:
    let #Some x = component_at a.values i else:
      return @panic "component membership invariant"
    let #Some y = component_at b.values i else:
      return @panic "component membership invariant"
    let #Some z = component_at c.values i else:
      return @panic "component membership invariant"
    return step i x y z) selected
  use replace_selected selected (patched_column a selected (fn at => do:
    let (x, _, _) = values[at]
    return x))
  use replace_selected selected (patched_column b selected (fn at => do:
    let (_, y, _) = values[at]
    return y))
  return replace_selected selected (patched_column c selected (fn at => do:
    let (_, _, z) = values[at]
    return z))

// Effectful visits retain their initial views, including membership, while callbacks edit the world.
const query = fn constructor => fn action => do:
  use source <- view constructor
  for word in source.occupied:
    let mask = word_mask source.bits word & word_mask source.masks word
    if mask != 0:
      for slot in 0 .. leaf_size:
        if (mask >> slot) & 1 != 0:
          let selected = (word << leaf_bits) + slot
          let #Some value = component_at source.values selected else:
            return @panic "component membership invariant"
          use at selected (fn () => action value)

const query_pair = fn left => fn right => fn action => do:
  use a <- view left
  use b <- view right
  let occupied = if a.occupied.length < b.occupied.length then a.occupied else b.occupied
  for word in occupied:
    let mask = word_mask a.bits word & word_mask a.masks word & word_mask b.masks word
    if mask != 0:
      for slot in 0 .. leaf_size:
        if (mask >> slot) & 1 != 0:
          let selected = (word << leaf_bits) + slot
          let #Some first = component_at a.values selected else:
            return @panic "component membership invariant"
          let #Some second = component_at b.values selected else:
            return @panic "component membership invariant"
          use at selected (fn () => action first second)

// Dense live component IDs in entity order, without a world-sized optional array.
const indices = fn (source: ReadView a) => do:
  let found = 0
  for word in source.occupied:
    let mask = word_mask source.bits word & word_mask source.masks word
    for slot in 0 .. leaf_size:
      if (mask >> slot) & 1 != 0:
        found := self + 1
  let selected = array.fill found 0
  let at = 0
  for word in source.occupied:
    let mask = word_mask source.bits word & word_mask source.masks word
    for slot in 0 .. leaf_size:
      if (mask >> slot) & 1 != 0:
        selected[at] := (word << leaf_bits) + slot
        at := self + 1
  return selected

// Insert, replace or remove a sparse batch, copying each touched leaf once. Inputs
// must be sorted/unique and name live entities; values use the same order.
const edit_selected = fn (constructor: p -> a) (selected: Array U32) (values: Array (Maybe a)) => do:
  if selected.length != values.length:
    return @panic "sparse component batch length mismatch"
  if selected.length == 0:
    return ()
  use current <- get #Entities
  for at in 0 .. selected.length:
    let index = selected[at]
    if index >= current.count || Bool.not (live current.bits index) || (at > 0 && selected[at - 1] >= index):
      return @panic "sparse component batch needs sorted unique live IDs"
  use column <- get (fn payload => make_column #[#[#[#Some (constructor payload)]]])
  let end = selected[selected.length - 1] + 1
  let blocks = array.generate (max column.values.length (units end block_bits)) (fn block =>
    if block < column.values.length then column.values[block] else #[])
  let masks = array.generate (max column.masks.length (units end leaf_bits)) (fn word => word_mask column.masks word)
  for first in 0 .. selected.length:
    let block = selected[first] >> block_bits
    if first == 0 || selected[first - 1] >> block_bits != block:
      let last = first
      for at in first .. selected.length:
        if selected[at] >> block_bits != block:
          break
        last := at
      let old = blocks[block]
      let needed = ((selected[last] >> leaf_bits) & branch_mask) + 1
      // Scoped set/remove assume every allocated leaf has all 32 slots,
      // including gaps before the first sparse write in this block.
      let leaves = array.generate (max old.length needed) (fn leaf =>
        if leaf < old.length then old[leaf] else array.fill leaf_size #Nothing)
      for at in first .. last + 1:
        let word = selected[at] >> leaf_bits
        if at == first || selected[at - 1] >> leaf_bits != word:
          let leaf = word & branch_mask
          let slots = array.generate leaf_size (fn slot => component_at column.values ((word << leaf_bits) + slot))
          let mask = masks[word]
          for index in at .. last + 1:
            if selected[index] >> leaf_bits != word:
              break
            let slot = selected[index] & leaf_mask
            slots[slot] := values[index]
            mask := if Maybe.is_some values[index] then self | (1 << slot) else self & (0xFFFFFFFF ^ (1 << slot))
          leaves[leaf] := slots
          masks[word] := mask
      blocks[block] := leaves
  column.values := blocks
  column.masks := masks
  column.occupied := occupied_words masks
  return replace_selected selected column

const insert_selected = fn (constructor: p -> a) selected (values: Array a) =>
  edit_selected constructor selected (array.map (fn value => #Some value) values)


// Known sparse writes inspect only touched memberships and journal those IDs.
const changed_column = fn (before: Column a) (next: Column a) (selected: Array U32) => do:
  let structural = #False
  let tracked = Maybe.is_some before.journal
  let entries = array.fill (if tracked then selected.length else 0) #journal.Replaced
  let count = 0
  for id in selected:
    let bit = 1 << (id & leaf_mask)
    let was = word_mask before.masks (id >> leaf_bits) & bit != 0
    let now = word_mask next.masks (id >> leaf_bits) & bit != 0
    structural := structural || (was && Bool.not now) || (now && Bool.not was)
    if tracked && (now || was):
      let entry = if now then (if was then #journal.Updated id else #journal.Added id) else #journal.Removed id
      entries[count] := entry
      count := self + 1
  next.revision := bumped_revision before.revision
  next.structure := if structural then bumped_revision before.structure else before.structure
  next.journal := Maybe.map (journal.record_many (array.slice 0 count entries)) before.journal
  return next


const replace_selected = fn selected next => do:
  use before <- get (fn () => next)
  return set (changed_column before next selected)

type ChangeCursor is data = #ChangeCursor { entities: U32, position: messages.Reader }
type ComponentChanges is data = #Delta { changes: changes.Changes, cursor: ChangeCursor } | #Reset ChangeCursor
const component_cursor = fn constructor => do:
  use current <- get #Entities
  use column <- get (fn payload => make_column #[#[#[#Some (constructor payload)]]])
  let #Some log = column.journal else:
    return @panic "component change tracking was not registered"
  return #ChangeCursor { entities: current.revision, position: journal.cursor log }
// Entity topology changes conservatively invalidate a component reader. This
// covers despawn without visiting every column or retaining dead components as
// live. Rebuild from a current view and adopt the returned cursor on Reset.
const component_changes = fn (reader: ChangeCursor) constructor -> ComponentChanges => do:
  use current <- get #Entities
  use column <- get (fn payload => make_column #[#[#[#Some (constructor payload)]]])
  let #Some log = column.journal else:
    return @panic "component change tracking was not registered"
  let cursor = #ChangeCursor { entities: current.revision, position: journal.cursor log }
  if reader.entities != current.revision:
    return #Reset cursor
  return case journal.read reader.position log of
    #journal.Reset _ => #Reset cursor
    #journal.Delta { changes } => #Delta { changes, cursor }

// Replace only the tracking timeline, leaving values and membership unchanged.
const restart_component_journal = fn (epoch: U32) constructor => do:
  use column <- get (fn payload => make_column #[#[#[#Some (constructor payload)]]])
  let #Some log = column.journal else:
    return @panic "component change tracking was not registered"
  column.journal := #Some (journal.restart epoch log)
  return set column

// Explicit identity-changing boundary. All registered current/previous columns
// are remapped together. The callback rewrites application references/resources
// and discards transient caches before the compacted world is published.
// previous[new] = old; current[old] = new or no_entity for a removed entity.
const compact = fn references => do:
  use before <- get #Entities
  let previous = #[index | index <- array.generate before.count identity, live before.bits index]
  let current = array.fill before.count no_entity
  for index in 0 .. previous.length:
    current[previous[index]] := index
  let remap = #Remap { previous, current }
  use Maintenance.remap previous
  let count = previous.length
  let bits = grown #[] 0 count
  use set #Entities { revision: bumped_revision before.revision, count, bits, occupied: occupied_words bits }
  use references remap
  return remap

sources.lib/physics.blot:
import * as graph from "./graph"
import * as spatial from "./spatial"
import * as joints from "./joints"
import * as array from "std/array"
import { Vec3 } from "std/vector"
import { Quat } from "./math"
import * as math from "./math"
import * as shapes from "./shapes"
import * as contact from "./contact"
import * as scene from "./scene"
import * as rigid from "./rigid"
import * as character from "./character"
import * as sort from "./sort"
import { Proxy, Rigid, Scene, Source, Walker } from "./scene"

// Characters move first; rigid solving updates the caller-owned contact cache.
// Source order and ascending U32 contact ids keep simulation deterministic.

type Config is data = #Config {
  gravity: Vec3,
  substeps: U32,
  sleep_time: F32,
  linear_sleep: F32,
  angular_sleep: F32,
}

// What a step changed on one source.
type Result is data = #Result {
  source: U32,
  position: Vec3,
  rotation: Quat,
  rigid: Maybe Rigid,
  walker: Maybe Walker,
}

// Caller-owned warm-start state. Entity ids remain U32 throughout simulation.
type CachedContact is data = #CachedContact {
  a: U32,
  b: U32,
  point: Vec3,
  normal: Vec3,
  normal_impulse: F32,
  tangent_impulse: Vec3,
}
type Cache is data = #Cache { contacts: Array CachedContact }
const empty_cache = #Cache { contacts: #[] }
const default_config = #Config {
  gravity: math.vec3 0.0 (-9.81) 0.0,
  substeps: 4,
  sleep_time: 0.5,
  linear_sleep: 0.05,
  angular_sleep: 0.05,
}

const no_slot = 0.0 - 1.0

const rigid_of = fn (source: Source) => case source.rigid of
  #Some r => r
  #Nothing => #scene.Rigid {
    kind: #scene.Static,
    mass: 1.0,
    gravity_scale: 1.0,
    linear_damping: 0.0,
    angular_damping: 0.0,
    can_sleep: #True,
    continuous: #False,
    linear_velocity: math.zero3,
    angular_velocity: math.zero3,
    sleeping: #False,
    sleep_time: 0.0,
  }

// The velocity a proxy moves with this step.
const velocity_of = fn (sources: Array Source) => fn (proxy: Proxy) => do:
  let source = sources[proxy.source]
  if proxy.walker:
    let #Some w = source.walker else:
      return math.zero3
    return w.velocity
  return (rigid_of source).linear_velocity

const is_mover = fn (proxy: Proxy) => proxy.kind >= scene.kind_kinematic && Bool.not proxy.trigger

// Which proxies are movers: kinematic and dynamic bodies, in order.
const mover_ids = fn (proxies: Array Proxy) => do:
  let found = @array.fill proxies.length 0
  let count = 0
  for i in 0..proxies.length:
    if is_mover proxies[i]:
      found[count] := i
      count := self + 1
  return @array.generate count (fn (k: U32) => found[k])

// Broad phase ------------------------------------------------------------------------

const layers_meet = fn (a: Proxy) => fn (b: Proxy) =>
  (a.layer & b.mask) != 0 && (b.layer & a.mask) != 0

// Sweep active movers along their widest axis; binary-search static bounds.
const broad_phase = fn proxies movers grow active => broad_phase_with #Nothing proxies movers grow active
// Reuse the caller's scene index. It must describe the current proxy bounds,
// including controller/CCD shifts. Active sweeps still use both travel margins.
const broad_phase_indexed = fn index proxies movers grow active => broad_phase_with (#Some index) proxies movers grow active
const broad_phase_with = fn (index: Maybe spatial.Index) (proxies: Array Proxy) (movers: Array U32) (grow: Array F32) (active: Array F32) => do:
  let m = movers.length
  let lo = @array.fill (m * 3) 0.0
  let hi = @array.fill (m * 3) 0.0
  let mine: List U32 = []
  for k in 0..m:
    if active[movers[k]] > 0.0:
      mine := [...self, k]
      let p = proxies[movers[k]]
      let g = grow[k]
      lo[k * 3] := p.low.x - g
      lo[k * 3 + 1] := p.low.y - g
      lo[k * 3 + 2] := p.low.z - g
      hi[k * 3] := p.high.x + g
      hi[k * 3 + 1] := p.high.y + g
      hi[k * 3 + 2] := p.high.z + g
  let live = Array.from_list mine
  let n = live.length
  let found: List U32 = []
  if n == 0:
    return #[]
  // Sweep along the axis where the active movers spread most.
  let mx = 0.0
  let my = 0.0
  let mz = 0.0
  for t in 0..n:
    let k = live[t]
    mx := self + lo[k * 3] + hi[k * 3]
    my := self + lo[k * 3 + 1] + hi[k * 3 + 1]
    mz := self + lo[k * 3 + 2] + hi[k * 3 + 2]
  let inv = 0.5 / U32.to_f32 n
  let vx = 0.0
  let vy = 0.0
  let vz = 0.0
  for t in 0..n:
    let k = live[t]
    let dx = (lo[k * 3] + hi[k * 3]) * 0.5 - mx * inv
    let dy = (lo[k * 3 + 1] + hi[k * 3 + 1]) * 0.5 - my * inv
    let dz = (lo[k * 3 + 2] + hi[k * 3 + 2]) * 0.5 - mz * inv
    vx := self + dx * dx
    vy := self + dy * dy
    vz := self + dz * dz
  let axis = 2
  if vy >= vz:
    axis := 1
  if vx >= vy && vx >= vz:
    axis := 0
  let keys = @array.generate n (fn (t: U32) => lo[live[t] * 3 + axis])
  let order = sort.order keys
  // Find each sweep interval's end before collecting pairs. Early loop exits
  // make the compiler copy the growing list on every append.
  for oi in 0..n:
    let i = live[order[oi]]
    let reach = hi[i * 3 + axis]
    let first = oi + 1
    let last = n
    for 0..32:
      if first < last:
        let mid = (first + last) / 2
        if lo[live[order[mid]] * 3 + axis] <= reach:
          first := mid + 1
        else:
          last := mid
    for oj in (oi + 1)..first:
      let j = live[order[oj]]
      if lo[i * 3] <= hi[j * 3] && hi[i * 3] >= lo[j * 3] && lo[i * 3 + 1] <= hi[j * 3 + 1] && hi[i * 3 + 1] >= lo[j * 3 + 1] && lo[i * 3 + 2] <= hi[j * 3 + 2] && hi[i * 3 + 2] >= lo[j * 3 + 2]:
        let pi = proxies[movers[i]]
        let pj = proxies[movers[j]]
        if (pi.kind == scene.kind_dynamic || pj.kind == scene.kind_dynamic) && layers_meet pi pj:
          let first = movers[i]
          let second = movers[j]
          found := [...self, first]
          found := [...self, second]
  // Active movers against everything at rest.
  let nr = 0
  for s in 0..proxies.length:
    if active[s] == 0.0 && Bool.not proxies[s].trigger:
      nr := self + 1
  // Small resting sets amortize no tree traversal. Private solver work scenes
  // may deliberately have no index, so retain the ordinary sweep fallback.
  if nr >= 64:
    if let #Some index = index:
      if index.order.length != proxies.length:
        return @panic "physics broad-phase index count mismatch"
      let indexed: List U32 = []
      for t in 0 .. n:
        let k = live[t]
        let pm = proxies[movers[k]]
        let low = math.vec3 lo[k * 3] lo[k * 3 + 1] lo[k * 3 + 2]
        let high = math.vec3 hi[k * 3] hi[k * 3 + 1] hi[k * 3 + 2]
        for source in spatial.query index low high:
          let ps = proxies[source]
          if active[source] == 0.0 && Bool.not ps.trigger && (pm.kind == scene.kind_dynamic || ps.kind == scene.kind_dynamic) && layers_meet pm ps && overlap_bounds lo hi k ps:
            indexed := [...self, movers[k]]
            indexed := [...self, source]
      return array.concat (Array.from_list found) (Array.from_list indexed)
  if nr > 0:
    let rest_ids = #[s | s <- array.generate proxies.length identity, active[s] == 0.0 && Bool.not proxies[s].trigger]
    let order_r = sort.order (@array.generate nr (fn (t: U32) => proxies[rest_ids[t]].low.x))
    let sorted = @array.generate nr (fn (t: U32) => rest_ids[order_r[t]])
    let low_x = @array.generate nr (fn (t: U32) => proxies[sorted[t]].low.x)
    let reach_x = @array.fill nr 0.0
    let running = (-1000000000.0)
    for t in 0..nr:
      running := max self proxies[sorted[t]].high.x
      reach_x[t] := running
    for t in 0..n:
      let k = live[t]
      let pm = proxies[movers[k]]
      // First resting proxy whose running maximum reaches the mover, and the
      // first whose low x is beyond it.
      let first = 0
      let last = nr
      for 0..32:
        if first < last:
          let mid = (first + last) / 2
          if reach_x[mid] < lo[k * 3]:
            first := mid + 1
          else:
            last := mid
      let begin = first
      first := 0
      last := nr
      for 0..32:
        if first < last:
          let mid = (first + last) / 2
          if low_x[mid] <= hi[k * 3]:
            first := mid + 1
          else:
            last := mid
      for u in begin..first:
        let ps = proxies[sorted[u]]
        if (pm.kind == scene.kind_dynamic || ps.kind == scene.kind_dynamic) && layers_meet pm ps && overlap_bounds lo hi k ps:
          let first_proxy = movers[k]
          let second_proxy = sorted[u]
          found := [...self, first_proxy]
          found := [...self, second_proxy]
  return Array.from_list found

const overlap_bounds = fn (lo: Array F32) => fn (hi: Array F32) => fn (k: U32) => fn (p: Proxy) =>
  lo[k * 3] <= p.high.x && hi[k * 3] >= p.low.x && lo[k * 3 + 1] <= p.high.y && hi[k * 3 + 1] >= p.low.y && lo[k * 3 + 2] <= p.high.z && hi[k * 3 + 2] >= p.low.z

// The pairs sorted by the smaller entity id, then the larger, and each pair
// ordered the same way. Input and output are flat proxy index lists.
const canonical_pairs = fn (proxies: Array Proxy) => fn (rank: Array U32) => fn (pairs: Array U32) => do:
  let count = pairs.length / 2
  let np = proxies.length
  let first = @array.generate count (fn (p: U32) => do:
    let a = pairs[p * 2]
    let b = pairs[p * 2 + 1]
    if rank[a] < rank[b]:
      return a
    return b)
  let second = @array.generate count (fn (p: U32) => do:
    let a = pairs[p * 2]
    let b = pairs[p * 2 + 1]
    if rank[a] < rank[b]:
      return b
    return a)
  if np <= 65535:
    let order = sort.order_u32 (@array.generate count (fn (p: U32) => rank[first[p]] * np + rank[second[p]]))
    return @array.generate (count * 2) (fn (k: U32) => do:
      let p = order[k / 2]
      if k % 2 == 0:
        return first[p]
      return second[p])
  let by_second = sort.order_u32 (@array.generate count (fn (p: U32) => proxies[second[p]].id))
  let by_first = sort.order_u32 (@array.generate count (fn (p: U32) => proxies[first[by_second[p]]].id))
  return @array.generate (count * 2) (fn (k: U32) => do:
    let p = by_second[by_first[k / 2]]
    if k % 2 == 0:
      return first[p]
    return second[p])

// Index of the first cache row for the pair (a, b), or the length if absent.
const cache_find = fn (cache: Cache) => fn (a: U32) => fn (b: U32) => do:
  let low = 0
  let high = cache.contacts.length
  for 0..32:
    if low >= high:
      break
    let mid = (low + high) / 2
    let c = cache.contacts[mid]
    if c.a < a || (c.a == a && c.b < b):
      low := mid + 1
    else:
      high := mid
  return low

// Reuse the nearest cached impulse for this exact entity pair: the normal
// impulse and the tangential impulse's x, y and z.
const cache_match = fn (cache: Cache) => fn (a: U32) => fn (b: U32) => fn (px: F32) => fn (py: F32) => fn (pz: F32) => do:
  let rows = cache.contacts.length
  let i = cache_find cache a b
  let best = 0.0225
  let jn = 0.0
  let jtx = 0.0
  let jty = 0.0
  let jtz = 0.0
  for 0..rows:
    if i >= rows:
      break
    let c = cache.contacts[i]
    if c.a != a || c.b != b:
      break
    let dx = c.point.x - px
    let dy = c.point.y - py
    let dz = c.point.z - pz
    let d = dx * dx + dy * dy + dz * dz
    if d < best:
      best := d
      jn := c.normal_impulse
      jtx := c.tangent_impulse.x
      jty := c.tangent_impulse.y
      jtz := c.tangent_impulse.z
    i := self + 1
  return (jn, jtx, jty, jtz)

const proxy_with_id = fn (proxies: Array Proxy) => fn (by_id: Array U32) => fn (id: U32) => do:
  let low = 0
  let high = by_id.length
  for 0..32:
    if low >= high:
      break
    let mid = (low + high) / 2
    if proxies[by_id[mid]].id < id:
      low := mid + 1
    else:
      high := mid
  if low < by_id.length && proxies[by_id[low]].id == id:
    return by_id[low]
  return proxies.length


// The first proxy with entity id `id`, or the proxy count, by binary search
// of `ids` (each proxy's id) in the stable ascending order `by_id`.
const index_of_id = fn (ids: Array U32) => fn (by_id: Array U32) => fn (id: U32) => do:
  let low = 0
  let high = by_id.length
  for 0..32:
    if low < high:
      let mid = (low + high) / 2
      if ids[by_id[mid]] < id:
        low := mid + 1
      else:
        high := mid
  if low < by_id.length && ids[by_id[low]] == id:
    return by_id[low]
  return ids.length

// Solver -----------------------------------------------------------------------------

type Island is data = #Island { parent: Array U32 }

const root_of = fn (parent: Array U32) => fn (i: U32) => do:
  let r = i
  for 0..parent.length:
    let p = parent[r]
    if p == r:
      break
    r := p
  return r

// Advance the rigid bodies by dt. `scene` holds the proxies; `sources` the
// matching entity data. Returns results for the bodies that moved and the new
// contact cache.
const contact_substeps = fn (substeps: U32) => fn (row_array: Array F32) => fn (inv_mass: Array F32) => fn (pos: Array F32) => do:
  // Height-ordered support chains need stiffer contacts above twelve bodies.
  let total = row_array.length / rigid.stride
  let m = inv_mass.length
  let under = @array.fill total 0
  let over = @array.fill total 0
  let heights = @array.fill total 0.0
  let supports = 0
  for c in 0..total:
    let o = c * rigid.stride
    let a = row_array[o]
    let b = row_array[o + 1]
    if a >= 0.0 && b >= 0.0:
      let ka = F32.to_u32 a
      let kb = F32.to_u32 b
      if inv_mass[ka] > 0.0 && inv_mass[kb] > 0.0:
        let ny = row_array[o + 3]
        if ny > 0.7:
          under[supports] := ka
          over[supports] := kb
          heights[supports] := pos[ka * 3 + 1]
          supports := self + 1
        if ny < (-0.7):
          under[supports] := kb
          over[supports] := ka
          heights[supports] := pos[kb * 3 + 1]
          supports := self + 1
  let depth = @array.fill m 1
  let deepest = 1
  if supports >= 11:
    let by_height = sort.order (@array.generate supports (fn (i: U32) => heights[i]))
    for r in 0..supports:
      let row = by_height[r]
      let reached = depth[under[row]] + 1
      if reached > depth[over[row]]:
        depth[over[row]] := reached
        deepest := max self reached
  if deepest >= 30:
    return min 16 (substeps * 4)
  if deepest >= 12:
    return min 16 (substeps * 2)
  return substeps

const prepare_joints = fn (joint_list: Array joints.Joint) => fn (sources: Array Source) => fn (sc: Scene) => fn (slot_of: Array F32) => do:
  let prepared: List joints.Link = []
  for joint in joint_list:
    if joint.a < sources.length && joint.b < sources.length && joints.valid joint:
      let a = sources[joint.a]
      let b = sources[joint.b]
      let slot_a = no_slot
      let slot_b = no_slot
      let proxy_a = sc.slots[joint.a]
      let proxy_b = sc.slots[joint.b]
      if proxy_a < slot_of.length:
        slot_a := slot_of[proxy_a]
      if proxy_b < slot_of.length:
        slot_b := slot_of[proxy_b]
      let body_a = rigid_of a
      let body_b = rigid_of b
      prepared := [...self, #joints.Link { joint, a: slot_a, b: slot_b, position_a: a.position, position_b: b.position, rotation_a: a.rotation, rotation_b: b.rotation, velocity_a: body_a.linear_velocity, velocity_b: body_b.linear_velocity, angular_a: body_a.angular_velocity, angular_b: body_b.angular_velocity }]
  return Array.from_list prepared

const sleep_islands = fn (config: Config) => fn (dt: F32) => fn (sources: Array Source) => fn (proxies: Array Proxy) => fn (movers: Array U32) => fn (connected: Array U32) => fn (inv_mass: Array F32) => fn (row_array: Array F32) => fn (new_vel: Array F32) => do:
  // Sleeping: islands of touching awake bodies sleep together once all of
  // them have been still for long enough.
  let m = movers.length
  let count = row_array.length / rigid.stride
  let parent = @array.generate m (fn (k: U32) => k)
  let sizes = @array.fill m 1
  for c in 0..count:
    let o = c * rigid.stride
    let a = row_array[o]
    let b = row_array[o + 1]
    if a >= 0.0 && b >= 0.0:
      let ka = F32.to_u32 a
      let kb = F32.to_u32 b
      if inv_mass[ka] > 0.0 && inv_mass[kb] > 0.0:
        // Find both roots inline: handing `parent` to a function would make
        // the union's writes below copy it.
        let ra = ka
        for 0..m:
          let up = parent[ra]
          if up == ra:
            break
          ra := up
        let rb = kb
        for 0..m:
          let up = parent[rb]
          if up == rb:
            break
          rb := up
        if ra != rb:
          // Size weighting bounds root walks even for dense canonical pairs.
          let size_a = sizes[ra]
          let size_b = sizes[rb]
          let smaller = ra
          let larger = rb
          if size_a > size_b || (size_a == size_b && ra < rb):
            smaller := rb
            larger := ra
          parent[smaller] := larger
          sizes[larger] := size_a + size_b
  let still = @array.fill m 0.0
  let island_time = @array.fill m 1000000.0
  for k in 0..m:
    if inv_mass[k] > 0.0:
      let proxy = proxies[movers[k]]
      let body = rigid_of sources[proxy.source]
      let v = k * 6
      let lin = sqrt (new_vel[v] * new_vel[v] + new_vel[v + 1] * new_vel[v + 1] + new_vel[v + 2] * new_vel[v + 2])
      let ang = sqrt (new_vel[v + 3] * new_vel[v + 3] + new_vel[v + 4] * new_vel[v + 4] + new_vel[v + 5] * new_vel[v + 5])
      let quiet = lin < config.linear_sleep && (ang < config.angular_sleep || ang * proxy.inscribed < config.linear_sleep) && body.can_sleep && connected[proxy.source] == 0
      let time = 0.0
      if quiet:
        time := body.sleep_time + dt
      still[k] := time
      let root = root_of parent k
      island_time[root] := min island_time[root] time
  return (parent, still, island_time)

const prepare_bodies = fn (sources: Array Source) => fn (proxies: Array Proxy) => fn (movers: Array U32) => fn (origins: Array Vec3) => fn (velocities: Array Vec3) => fn (woke: Array F32) => do:
  let np = proxies.length
  let m = movers.length
  let slot_of = @array.fill np no_slot
  for k in 0..m:
    slot_of[movers[k]] := U32.to_f32 k
  let pos = @array.fill (m * 3) 0.0
  let rot = @array.fill (m * 4) 0.0
  let vel = @array.fill (m * 6) 0.0
  let inv_mass = @array.fill m 0.0
  let inv_inertia = @array.fill (m * 3) 0.0
  let gravity_scale = @array.fill m 0.0
  let linear_damping = @array.fill m 0.0
  let angular_damping = @array.fill m 0.0
  for k in 0..m:
    let proxy = proxies[movers[k]]
    let source = sources[proxy.source]
    let body = rigid_of source
    pos[k * 3] := origins[movers[k]].x
    pos[k * 3 + 1] := origins[movers[k]].y
    pos[k * 3 + 2] := origins[movers[k]].z
    rot[k * 4] := source.rotation.x
    rot[k * 4 + 1] := source.rotation.y
    rot[k * 4 + 2] := source.rotation.z
    rot[k * 4 + 3] := source.rotation.w
    let v = velocities[movers[k]]
    vel[k * 6] := v.x
    vel[k * 6 + 1] := v.y
    vel[k * 6 + 2] := v.z
    vel[k * 6 + 3] := body.angular_velocity.x
    vel[k * 6 + 4] := body.angular_velocity.y
    vel[k * 6 + 5] := body.angular_velocity.z
    if proxy.kind == scene.kind_dynamic && woke[movers[k]] > 0.0:
      let mass = max 0.0001 body.mass
      inv_mass[k] := 1.0 / mass
      inv_inertia[k * 3] := 1.0 / (mass * max 0.00001 proxy.inertia.x)
      inv_inertia[k * 3 + 1] := 1.0 / (mass * max 0.00001 proxy.inertia.y)
      inv_inertia[k * 3 + 2] := 1.0 / (mass * max 0.00001 proxy.inertia.z)
      gravity_scale[k] := body.gravity_scale
      linear_damping[k] := body.linear_damping
      angular_damping[k] := body.angular_damping
  let bodies = #rigid.Bodies { pos, rot, vel, inv_mass, inv_inertia, gravity_scale, linear_damping, angular_damping }
  return (bodies, slot_of)

const prepare_contacts = fn (dt: F32) => fn (proxies: Array Proxy) => fn (velocities: Array Vec3) => fn (woke: Array F32) => fn (by_id: Array U32) => fn (candidates: Array U32) => fn (bodies: rigid.Bodies) => fn (slot_of: Array F32) => fn (cache: Cache) => do:
  let np = proxies.length
  let rank = @array.fill np 0
  for t in 0..np:
    rank[by_id[t]] := t
  let pairs = canonical_pairs proxies rank candidates
  let iw0 = rigid.inertia_table bodies.rot bodies.inv_inertia
  // Find every pair's contacts first, so the row tables are allocated at
  // their exact size.
  let pair_count = pairs.length / 2
  // How far each pair closes during the step.
  let closing = @array.generate pair_count (fn (p: U32) => do:
    let va = velocities[pairs[p * 2]]
    let vb = velocities[pairs[p * 2 + 1]]
    let dx = va.x - vb.x
    let dy = va.y - vb.y
    let dz = va.z - vb.z
    return sqrt (dx * dx + dy * dy + dz * dz) * dt)
  let found = @array.generate pair_count (fn (p: U32) => do:
    let ia = pairs[p * 2]
    let ib = pairs[p * 2 + 1]
    if woke[ia] > 0.0 || woke[ib] > 0.0:
      return contact.between proxies[ia].shape proxies[ib].shape (0.02 + closing[p])
    return #[])
  // Omit contacts that cannot close during this step.
  let reach = @array.generate pair_count (fn (p: U32) => 0.008 + closing[p])
  let used = 0
  for p in 0..pair_count:
    let limit = reach[p]
    for c in found[p]:
      if c.sep <= limit:
        used := self + 1
  let row_buf = @array.fill (used * rigid.stride) 0.0
  let imp_buf = @array.fill (used * rigid.impulse_stride) 0.0
  let row_a_ids = @array.fill used 0
  let row_b_ids = @array.fill used 0
  let r = 0
  for p in 0..pair_count:
    let ia = pairs[p * 2]
    let ib = pairs[p * 2 + 1]
    let pa = proxies[ia]
    let pb = proxies[ib]
    let a = slot_of[ia]
    let b = slot_of[ib]
    let friction = sqrt (pa.friction * pb.friction)
    let restitution = max pa.restitution pb.restitution
    let limit = reach[p]
    for c in found[p]:
      if c.sep <= limit:
        let point = c.point
        let normal = c.normal
        let row = rigid.prepare_row_xyz bodies iw0 a b normal.x normal.y normal.z point.x point.y point.z c.sep friction restitution
        let (jn, jtx, jty, jtz) = cache_match cache pa.id pb.id point.x point.y point.z
        let ro = r * rigid.stride
        for k in 0..rigid.stride:
          row_buf[ro + k] := row[k]
        row_a_ids[r] := pa.id
        row_b_ids[r] := pb.id
        let io = r * rigid.impulse_stride
        imp_buf[io] := jn
        imp_buf[io + 1] := jtx * row[17] + jty * row[18] + jtz * row[19]
        imp_buf[io + 2] := jtx * row[20] + jty * row[21] + jtz * row[22]
        r := self + 1
  return (row_buf, imp_buf, row_a_ids, row_b_ids)

// Results for the woken dynamic bodies, in mover order, gathered by index
// into an exactly sized array: appending records to a List one at a time
// costs more with every append.
const moved_results = fn (config: Config) => fn (sources: Array Source) => fn (proxies: Array Proxy) => fn (movers: Array U32) => fn (woke: Array F32) => fn (parent: Array U32) => fn (island_time: Array F32) => fn (still: Array F32) => fn (new_pos: Array F32) => fn (new_rot: Array F32) => fn (new_vel: Array F32) => do:
  let m = movers.length
  let slots = @array.fill m 0
  let count = 0
  for k in 0..m:
    let idx = movers[k]
    if proxies[idx].kind == scene.kind_dynamic && woke[idx] > 0.0:
      slots[count] := k
      count := self + 1
  return @array.generate count (fn (r: U32) => do:
    let k = slots[r]
    let proxy = proxies[movers[k]]
    let body = rigid_of sources[proxy.source]
    let root = root_of parent k
    let sleep_now = island_time[root] >= config.sleep_time
    let v = k * 6
    let lin = if sleep_now then math.zero3 else #Vec3 { x: new_vel[v], y: new_vel[v + 1], z: new_vel[v + 2] }
    let ang = if sleep_now then math.zero3 else #Vec3 { x: new_vel[v + 3], y: new_vel[v + 4], z: new_vel[v + 5] }
    let updated = #scene.Rigid {
      kind: body.kind, mass: body.mass, gravity_scale: body.gravity_scale,
      linear_damping: body.linear_damping, angular_damping: body.angular_damping,
      can_sleep: body.can_sleep, continuous: body.continuous,
      linear_velocity: lin, angular_velocity: ang,
      sleeping: sleep_now, sleep_time: still[k],
    }
    return #Result {
      source: proxy.source,
      position: rigid.vec new_pos (k * 3),
      rotation: rigid.quat new_rot (k * 4),
      rigid: #Some updated,
      walker: #Nothing,
    })

const simulate_queries = fn (queries: scene.Queries) => fn (joint_list: Array joints.Joint) => fn (config: Config) => fn (dt: F32) => fn (sources: Array Source) => fn (sc: Scene) => fn (cache: Cache) => do:
  if Bool.not (dt > 0.0 && dt - dt == 0.0):
    return (#[], cache)
  let np = scene.count sc
  // One loop fills the per-proxy arrays together; the walker and sweep loops
  // below write them in place.
  let original = scene.proxies sc
  let proxies = @array.generate np (fn (i: U32) => original[i])
  // Explicit joints wake their connected dynamics.
  let connected = @array.fill sources.length 0
  for joint in joint_list:
    if joints.valid joint && joint.a < sources.length && joint.b < sources.length:
      connected[joint.a] := 1
      connected[joint.b] := 1
  let origins = @array.fill np math.zero3
  let velocities = @array.fill np math.zero3
  let angulars = @array.fill np math.zero3
  // Awake flags per proxy: 1 for dynamic bodies that are not asleep.
  let awake = @array.fill np 0.0
  for i in 0..np:
    let p = proxies[i]
    origins[i] := sources[p.source].position
    if p.kind >= scene.kind_kinematic:
      velocities[i] := velocity_of sources p
      if Bool.not p.walker:
        angulars[i] := (rigid_of sources[p.source]).angular_velocity
    if p.kind == scene.kind_dynamic && Bool.not p.trigger:
      if connected[p.source] > 0 || Bool.not (rigid_of sources[p.source]).sleeping:
        awake[i] := 1.0
  // Proxy ids in stable ascending order; moving proxies keeps their ids.
  let ids = @array.generate np (fn (i: U32) => original[i].id)
  let by_id = sort.order_u32 ids
  // Characters move first, on the world as it stood; they shove dynamic
  // bodies they walk into and leave their motion as a velocity for the solver.
  // The loop writes the per-proxy arrays in place, so it hands them to no
  // function, and it records each walker's outcome for an exact result array.
  let walked = @array.fill np 0
  let walked_at = @array.fill np math.zero3
  let walked_state = @array.fill np scene.default_walker
  let wake_by_push = @array.fill np 0.0
  let shifted: List U32 = []
  for i in 0..np:
    let proxy = proxies[i]
    if proxy.walker && Bool.not proxy.trigger:
      let source = sources[proxy.source]
      if let #Some walker = source.walker:
        if let #shapes.Capsule { a, b, radius } = proxy.shape:
          let body = #character.Body { low: a - source.position, high: b - source.position, radius }
          let filter = #scene.Filter { mask: proxy.mask, skip: proxy.id, triggers: #False, walkers: #False, dynamics: #True }
          let under = if walker.ground == 0 then np else index_of_id ids by_id walker.ground
          // How far the platform underfoot moved this step: its translation
          // plus the turn about its own origin, at the character's feet.
          let carry = math.zero3
          if walker.grounded && under < np:
            let platform = proxies[under]
            if platform.kind != scene.kind_static:
              let origin = sources[platform.source].position
              carry := (velocities[under] + angulars[under].cross (source.position - origin)) * dt
          let moved = character.move_queries queries body filter source.position walker carry dt
          let shift = moved.position - source.position
          proxies[i] := scene.shifted proxy shift
          if shift.x != 0.0 || shift.y != 0.0 || shift.z != 0.0:
            shifted := [...self, i]
          origins[i] := moved.position
          velocities[i] := shift / dt
          for h in moved.hits:
            if h.proxy < np:
              let other = proxies[h.proxy]
              if other.kind == scene.kind_dynamic && Bool.not other.trigger:
                let away = shapes.neg h.normal
                let approach = max 0.0 (away.dot walker.velocity)
                let current = velocities[h.proxy].dot away
                let extra = max 0.0 (approach * walker.push - current)
                velocities[h.proxy] := velocities[h.proxy] + away * extra
                if extra > 0.0:
                  wake_by_push[h.proxy] := 1.0
          walked[i] := 1
          walked_at[i] := moved.position
          walked_state[i] := moved.walker
  // Sweep each fast body's inscribed sphere against immovable colliders.
  for i in 0..np:
    let proxy = proxies[i]
    if proxy.kind == scene.kind_dynamic && awake[i] > 0.0 && Bool.not proxy.trigger:
      let body = rigid_of sources[proxy.source]
      let delta = velocities[i] * dt
      let travel = delta.length
      if body.continuous && travel > proxy.inscribed * 0.5 && travel > 0.0001:
        let filter = #scene.Filter { mask: proxy.mask, skip: proxy.id, triggers: #False, walkers: #False, dynamics: #False }
        if let #Some h = scene.query_cast queries origins[i] origins[i] proxy.inscribed delta filter:
          if h.depth == 0.0:
            let shift = delta * max 0.0 (h.time - 0.01 / travel)
            proxies[i] := scene.shifted proxy shift
            shifted := [...self, i]
            origins[i] := origins[i] + shift
  let movers = mover_ids proxies
  let m = movers.length
  let grow = @array.generate m (fn (k: U32) => 0.04 + (velocities[movers[k]]).length * dt)
  // Active: awake or pushed dynamic bodies, moving kinematic bodies.
  let woke = @array.generate np (fn (i: U32) => max awake[i] wake_by_push[i])
  let active0 = @array.fill np 0.0
  let resting = 0
  let active_count = 0
  for i in 0..np:
    if woke[i] > 0.0 || (proxies[i].kind == scene.kind_kinematic && Bool.not proxies[i].trigger && velocities[i].length_squared > 0.0000001):
      active0[i] := 1.0
      active_count := self + 1
    else:
      if Bool.not proxies[i].trigger:
        resting := self + 1
  let broad_index = #Nothing
  if resting >= 64 && active_count > 0 && sc.index.order.length == np:
    let dirty = Array.from_list shifted
    let bounds = array.map (fn i => #spatial.Bounds {low: proxies[i].low, high: proxies[i].high}) dirty
    broad_index := #Some (spatial.refit sc.index dirty bounds)
  let candidates0 = broad_phase_with broad_index proxies movers grow active0
  // Active contacts wake sleepers and propagate through cached support pairs.
  let pair_count = candidates0.length / 2
  let woken = #False
  for p in 0..pair_count:
    let a = candidates0[p * 2]
    let b = candidates0[p * 2 + 1]
    if proxies[a].kind == scene.kind_dynamic && woke[a] == 0.0 && active0[b] > 0.0:
      woke[a] := 1.0
      woken := #True
    if proxies[b].kind == scene.kind_dynamic && woke[b] == 0.0 && active0[a] > 0.0:
      woke[b] := 1.0
      woken := #True
  let cache_rows = cache.contacts.length
  let row_a = @array.generate cache_rows (fn (r: U32) => proxy_with_id proxies by_id cache.contacts[r].a)
  let row_b = @array.generate cache_rows (fn (r: U32) => proxy_with_id proxies by_id cache.contacts[r].b)
  if woken:
    if cache_rows > 0x7FFFFFFF:
      return @panic "contact wake edge count overflows"
    let endpoints = @array.fill (cache_rows * 2) 0
    let targets = @array.fill (cache_rows * 2) 0
    let used = 0
    for r in 0 .. cache_rows:
      let a = row_a[r]
      let b = row_b[r]
      if a < np && b < np:
        endpoints[used] := a
        targets[used] := b
        endpoints[used + 1] := b
        targets[used + 1] := a
        used := self + 2
    let #Some adjacency = graph.from_edges np (@array.slice endpoints 0 used) (@array.slice targets 0 used) else:
      return @panic "contact wake adjacency invariant"
    let roots = #[i | i <- @array.generate np (fn i => i), woke[i] > 0.0]
    let active = graph.reachable adjacency roots (@array.generate np (fn i => proxies[i].kind == scene.kind_dynamic))
    woke := @array.generate np (fn i => if active[i] then 1.0 else 0.0)
  // Bodies that just woke now need their contacts with everything near.
  let active1 = @array.generate np (fn (i: U32) => do:
    if woke[i] > 0.0 || active0[i] > 0.0:
      return 1.0
    return 0.0)
  let candidates = candidates0
  if woken:
    candidates := broad_phase_with broad_index proxies movers grow active1
  let (bodies, slot_of) = prepare_bodies sources proxies movers origins velocities woke
  let (row_array, imp_array, row_a_ids, row_b_ids) = prepare_contacts dt proxies velocities woke by_id candidates bodies slot_of cache
  let substeps = contact_substeps config.substeps row_array bodies.inv_mass bodies.pos
  let prepared = prepare_joints joint_list sources sc slot_of
  let (new_pos, new_rot, new_vel, solved) = rigid.solve_joints prepared dt substeps config.gravity bodies row_array imp_array
  let (parent, still, island_time) = sleep_islands config dt sources proxies movers connected bodies.inv_mass row_array new_vel
  let count = row_array.length / rigid.stride
  // Merge solved and unchanged sleeping contacts in exact U32 id order.
  let fresh = @array.generate count (fn (c: U32) => do:
    let o = c * rigid.stride
    let q = c * rigid.impulse_stride
    let jt1 = solved[q + 1]
    let jt2 = solved[q + 2]
    return #CachedContact {
      a: row_a_ids[c], b: row_b_ids[c],
      point: rigid.vec row_array (o + 24),
      normal: rigid.vec row_array (o + 2),
      normal_impulse: solved[q],
      tangent_impulse: #Vec3 {
        x: row_array[o + 17] * jt1 + row_array[o + 20] * jt2,
        y: row_array[o + 18] * jt1 + row_array[o + 21] * jt2,
        z: row_array[o + 19] * jt1 + row_array[o + 22] * jt2,
      },
    })
  let kept_rows = @array.fill cache_rows 0
  let kept = 0
  for r in 0..cache_rows:
    let ia = row_a[r]
    let ib = row_b[r]
    if ia < np && ib < np && woke[ia] == 0.0 && woke[ib] == 0.0:
      kept_rows[kept] := r
      kept := self + 1
  let carried = @array.generate kept (fn (r: U32) => cache.contacts[kept_rows[r]])
  let merged = merge_caches (#Cache { contacts: fresh }) (#Cache { contacts: carried })
  let bodies_moved = moved_results config sources proxies movers woke parent island_time still new_pos new_rot new_vel
  let walker_slots = @array.fill np 0
  let walkers = 0
  for i in 0..np:
    if walked[i] > 0:
      walker_slots[walkers] := i
      walkers := self + 1
  let walker_results = @array.generate walkers (fn (r: U32) => do:
    let i = walker_slots[r]
    let source = proxies[i].source
    return #Result { source, position: walked_at[i], rotation: sources[source].rotation, rigid: #Nothing, walker: #Some walked_state[i] })
  return (array.concat walker_results bodies_moved, merged)

const merge_caches = fn (a: Cache) => fn (b: Cache) => do:
  if b.contacts.is_empty:
    return a
  let na = a.contacts.length
  let nb = b.contacts.length
  // The merged order as indices: below na from a, from na on from b.
  let order = @array.fill (na + nb) 0
  let i = 0
  let j = 0
  for k in 0..(na + nb):
    let take_a = #False
    if j >= nb:
      take_a := #True
    else:
      if i < na:
        let ca = a.contacts[i]
        let cb = b.contacts[j]
        take_a := ca.a < cb.a || (ca.a == cb.a && ca.b <= cb.b)
    // One write a step: writes under both arms would copy the array.
    let at = na + j
    if take_a:
      at := i
      i := self + 1
    else:
      j := self + 1
    order[k] := at
  return #Cache { contacts: @array.generate (na + nb) (fn (k: U32) => do:
    let at = order[k]
    if at < na:
      return a.contacts[at]
    return b.contacts[at - na]) }

// Contact-only simulation retains its original API.
const simulate_joints = fn links => fn config => fn dt => fn sources => fn (sc: Scene) =>
  simulate_queries (scene.queries sc) links config dt sources sc

const simulate = fn (config: Config) => fn (dt: F32) => fn (sources: Array Source) => fn (sc: Scene) => fn (cache: Cache) => simulate_joints #[] config dt sources sc cache

// Apply a step to caller-owned sources. Kinematic poses remain caller supplied.
const apply = fn (sources: Array Source) => fn (results: Array Result) => do:
  let next = @array.generate sources.length (fn (i: U32) => sources[i])
  for r in results:
    let s = next[r.source]
    s.position := r.position
    s.rotation := r.rotation
    if let #Some rigid = r.rigid:
      s.rigid := #Some rigid
    if let #Some walker = r.walker:
      s.walker := #Some walker
    next[r.source] := s
  return next

// Convenience for small scenes; use scene.update + simulate to reuse geometry.
const step = fn (config: Config) => fn (dt: F32) => fn (sources: Array Source) => fn (cache: Cache) => do:
  let (results, next_cache) = simulate config dt sources (scene.build sources) cache
  return (apply sources results, next_cache)

// Joint simulation shares contact cache and integration with ordinary physics.
const step_joints = fn (joint_list: Array joints.Joint) => fn (config: Config) => fn (dt: F32) => fn (sources: Array Source) => fn (cache: Cache) => do:
  let (results, next_cache) = simulate_joints joint_list config dt sources (scene.build sources) cache
  return (apply sources results, next_cache)

// Queries take built scenes and layer masks; only overlaps include triggers.

const all_layers: U32 = 65535

// The first solid hit along a ray of length `reach`, ignoring the entity
// `skip` (0 for none): `physics.ray scene origin direction reach mask skip`.
const ray = fn (sc: Scene) => fn (origin: Vec3) => fn (direction: Vec3) => fn (reach: F32) => fn (mask: U32) => fn (skip: U32) => scene.ray sc origin direction reach mask skip

// Move a sphere by `delta`; the first thing it touches.
const sweep_sphere = fn (sc: Scene) => fn (center: Vec3) => fn (radius: F32) => fn (delta: Vec3) => fn (mask: U32) => fn (skip: U32) =>
  scene.cast sc center center radius delta (#scene.Filter { mask, skip, triggers: #False, walkers: #True, dynamics: #True })

// Move a capsule (the segment a-b with a radius) by `delta`.
const sweep_capsule = fn (sc: Scene) => fn (a: Vec3) => fn (b: Vec3) => fn (radius: F32) => fn (delta: Vec3) => fn (mask: U32) => fn (skip: U32) =>
  scene.cast sc a b radius delta (#scene.Filter { mask, skip, triggers: #False, walkers: #True, dynamics: #True })

// The entity ids overlapping a sphere or a capsule, triggers included.
const overlap_sphere = fn (sc: Scene) => fn (center: Vec3) => fn (radius: F32) => fn (mask: U32) => scene.overlap_sphere sc center radius mask
const overlap_capsule = fn (sc: Scene) => fn (a: Vec3) => fn (b: Vec3) => fn (radius: F32) => fn (mask: U32) => scene.overlap_capsule sc a b radius mask

// Is the point inside anything solid?
const point_solid = fn (sc: Scene) => fn (p: Vec3) => fn (mask: U32) => scene.point_solid sc p mask

// Did the last step have a contact between these two entities? `contacts` is
// the contact cache returned by `simulate`.
const touching = fn (cache: Cache) => fn (a: U32) => fn (b: U32) => do:
  let low = min a b
  let high = a
  if a < b:
    high := b
  let i = cache_find cache low high
  return i < cache.contacts.length && cache.contacts[i].a == low && cache.contacts[i].b == high

const contact_count = fn (cache: Cache) => cache.contacts.length

sources.lib/physics/prepared.blot:
import * as character from "../character"
import * as shapes from "../shapes"
import * as changes from "../changes"
import * as array from "std/array"
import * as pages from "../pages"
import * as math from "../math"
import * as physics from "../physics"
import * as scene from "../scene"
import * as sort from "../sort"
import { Vec3 } from "std/vector"
import * as spatial from "../spatial"
import * as joints from "../joints"

// Immutable authored colliders. Bodies supplied to simulate remain caller-owned;
// result.source and joint indices address [moving sources, fixed sources].
// Fixed sources never produce movement results. Rebuild this value when static
// geometry changes; old prepared worlds and contact caches remain usable.
type Static is data = #Static { sources: Array scene.Source, scene: scene.Scene, ids: Array U32, by_id: Array U32 }
const prepare = fn (sources: Array scene.Source) => do:
  for source in sources:
    if Maybe.is_some source.walker:
      return #Nothing
    if let #Some body = source.rigid:
      let fixed = case body.kind of
        #scene.Static => #True
        _ => #False
      if Bool.not fixed:
        return #Nothing
  let built = scene.build sources
  let ids = array.map (fn (p: scene.Proxy) => p.id) (scene.proxies built)
  return #Some (#Static { sources, scene: built, ids, by_id: sort.order_u32 ids })
const find = fn (fixed: Static) => fn id => do:
  let low = 0
  let high = fixed.ids.length
  for 0 .. 32:
    if low >= high:
      break
    let middle = low + (high - low) / 2
    if fixed.ids[fixed.by_id[middle]] < id:
      low := middle + 1
    else:
      high := middle
  if low < fixed.ids.length:
    let index = fixed.by_id[low]
    if fixed.ids[index] == id:
      return #Some index
  return #Nothing

// Predict the existing controller pass against both immutable indexes. The
// solver repeats the same pass; this preview only selects its static contacts.
// Include pushes before sizing dynamic CCD envelopes, and moving-platform carry.
const preview = fn (queries: scene.Queries) => fn (moving: Array scene.Source) => fn (built: scene.Scene) => fn dt => do:
  let original = scene.proxies built
  let count = original.length
  let proxies = array.generate count (fn i => original[i])
  let velocities = array.generate count (fn i => physics.velocity_of moving original[i])
  for i in 0 .. count:
    let proxy = original[i]
    if proxy.walker && Bool.not proxy.trigger:
      let source = moving[proxy.source]
      if let #Some walker = source.walker:
        if let #shapes.Capsule { a, b, radius } = proxy.shape:
          let body = #character.Body { low: a - source.position, high: b - source.position, radius }
          let filter = #scene.Filter { mask: proxy.mask, skip: proxy.id, triggers: #False, walkers: #False, dynamics: #True }
          let carry = math.zero3
          if walker.grounded:
            for under in 0 .. count:
              let platform = proxies[under]
              if platform.id == walker.ground && platform.kind != scene.kind_static:
                let other = moving[platform.source]
                let angular = if platform.walker then math.zero3 else (physics.rigid_of other).angular_velocity
                carry := (velocities[under] + angular.cross (source.position - other.position)) * dt
          let moved = character.move_queries queries body filter source.position walker carry dt
          let shift = moved.position - source.position
          proxies[i] := scene.shifted proxy shift
          velocities[i] := shift / dt
          for hit in moved.hits:
            if hit.proxy < count:
              let other = proxies[hit.proxy]
              if other.kind == scene.kind_dynamic && Bool.not other.trigger:
                let away = shapes.neg hit.normal
                let approach = max 0.0 (away.dot walker.velocity)
                let current = velocities[hit.proxy].dot away
                let extra = max 0.0 (approach * walker.push - current)
                velocities[hit.proxy] := velocities[hit.proxy] + away * extra
  return (proxies, velocities)

// Static source slots, in authored order. Explicit joint endpoints are included
// even when they have no collider, so anchors retain their original poses.
const select = fn (fixed: Static) => fn (proxies: Array scene.Proxy) => fn (velocities: Array Vec3) => fn (seconds: F32) => fn (cache: physics.Cache) => fn (moving_count: U32) => fn (links: Array joints.Joint) => do:
  let candidates: List U32 = []
  for i in 0 .. proxies.length:
    let p = proxies[i]
    let v = velocities[i]
    let speed = sqrt (v.x * v.x + v.y * v.y + v.z * v.z)
    let grow = 0.04 + speed * seconds * 2.0
    let low = math.vec3 (p.low.x - grow) (p.low.y - grow) (p.low.z - grow)
    let high = math.vec3 (p.high.x + grow) (p.high.y + grow) (p.high.z + grow)
    for index in spatial.query fixed.scene.index low high:
      candidates := [...self, (scene.proxy fixed.scene index).source]
  for contact in cache.contacts:
    if let #Some index = find fixed contact.a:
      candidates := [...self, (scene.proxy fixed.scene index).source]
    if let #Some index = find fixed contact.b:
      candidates := [...self, (scene.proxy fixed.scene index).source]
  for link in links:
    if joints.valid link && link.a < moving_count + fixed.sources.length && link.b < moving_count + fixed.sources.length:
      if link.a >= moving_count:
        candidates := [...self, link.a - moving_count]
      if link.b >= moving_count:
        candidates := [...self, link.b - moving_count]
  return changes.unique (Array.from_list candidates)

const assemble = fn (fixed: Static) => fn (moving: Array scene.Source) => fn (built: scene.Scene) => fn (selected: Array U32) => do:
  let sources = array.generate (moving.length + selected.length) (fn i =>
    if i < moving.length then moving[i] else fixed.sources[selected[i - moving.length]])
  let shaped: List U32 = []
  for i in 0 .. selected.length:
    if fixed.scene.slots[selected[i]] < (scene.count fixed.scene):
      shaped := [...self, i]
  let shaped = Array.from_list shaped
  let first = (scene.count built)
  let proxies = array.generate (first + shaped.length) (fn i => do:
    if i < first:
      return (scene.proxy built i)
    let selected_at = shaped[i - first]
    let proxy = (scene.proxy fixed.scene fixed.scene.slots[selected[selected_at]])
    proxy.source := moving.length + selected_at
    return proxy)
  let slots = array.fill sources.length proxies.length
  for i in 0 .. proxies.length:
    slots[proxies[i].source] := i
  // Queries use the original independent indexes. This private work scene only
  // supplies the solver's source/proxy mapping and needs no rebuilt BVH.
  return (sources, #scene.Scene { proxies: pages.from proxies, index: spatial.build #[], slots, source_count: sources.length })
const remap = fn (moving: U32) => fn (selected: Array U32) => fn (source: U32) => do:
  if source < moving:
    return source
  let target = source - moving
  let low = 0
  let high = selected.length
  for 0 .. 32:
    if low >= high:
      break
    let middle = low + (high - low) / 2
    if selected[middle] < target:
      low := middle + 1
    else:
      high := middle
  if low < selected.length && selected[low] == target:
    return moving + low
  return moving + selected.length
const simulate_joints = fn (fixed: Static) => fn (links: Array joints.Joint) => fn config => fn (seconds: F32) => fn (moving: Array scene.Source) => fn cache => do:
  if Bool.not (seconds > 0.0 && is_finite seconds):
    return (#[], cache)
  let built = scene.build moving
  let queries = scene.together (scene.queries built) (scene.queries fixed.scene)
  let (proxies, velocities) = preview queries moving built seconds
  let selected = select fixed proxies velocities seconds cache moving.length links
  let (sources, sc) = assemble fixed moving built selected
  let mapped = array.map (fn (link: joints.Joint) => do:
    link.a := remap moving.length selected self
    link.b := remap moving.length selected self
    return link) links
  return physics.simulate_queries queries mapped config seconds sources sc cache
const simulate = fn fixed => simulate_joints fixed #[]

pagedMaskPrototype.source:
import * as array from "std/array"
import * as pages from "ink/pages"
const changing = fn paged (count: U32) => do:
  let original = array.fill count 1
  let flat = original
  let stored = pages.from original
  for step in 0 .. 16:
    let index = step * 4093 % count
    if paged:
      stored := pages.set index 2 self
    else:
      let before = flat
      flat := array.generate count (fn i => if i == index then 2 else before[i])
  let values = array.generate 16 (fn step => do:
    let index = step * 4093 % count
    return if paged then pages.get stored index else flat[index])
  return array.concat #[original[0]] values
entry const update_flat = changing #False
entry const update_paged = changing #True
entry const scan_flat = fn (count: U32) => do:
  let flat = array.fill count 1
  let total = 0
  for pass in 0 .. 16:
    for i in 0 .. count:
      total := self + flat[i]
  return #[total]
entry const scan_paged = fn (count: U32) => do:
  let stored = pages.from (array.fill count 1)
  let total = 0
  for pass in 0 .. 16:
    for i in 0 .. count:
      total := self + pages.get stored i
  return #[total]
entry const scan_leaves = fn (count: U32) => do:
  let flat = array.fill count 1
  let stored = pages.from flat
  let leaves = pages.leaves stored
  let total = 0
  for pass in 0 .. 16:
    for i in 0 .. count:
      total := self + leaves[i >> 6][i & 63]
  return #[total]

pagedMaskPrototype.runner:
use ink_tools::{Fixture, compiled};
use serde_json::json;
use std::time::Instant;

fn main() {
    std::fs::create_dir_all(".cache/six-more").unwrap();
    let module = compiled(".cache/six-more/mask-prototype.blot", &[]);
    let mut guest = Fixture::from_module(&module);
    let mut report = vec![];
    for (scalar, vector, sizes) in [
        ("update_flat", "update_paged", vec![4096u32, 65536, 262144]),
        ("scan_flat", "scan_paged", vec![4096u32, 65536, 262144]),
        ("scan_flat", "scan_leaves", vec![4096u32, 65536, 262144]),
    ] {
        for size in sizes {
            let expected = guest.call(scalar, size).unwrap();
            let reference = if scalar == "update_flat" {
                let mut values = vec![1];
                values.extend([2; 16]);
                values
            } else { vec![size * 16] };
            assert_eq!(expected, blot_host::Value::ArrayU32(reference));
            assert_eq!(expected, guest.call(vector, size).unwrap());
            for _ in 0..5 {
                assert_eq!(expected, guest.call(scalar, size).unwrap());
                assert_eq!(expected, guest.call(vector, size).unwrap());
            }
            let memory_before = guest.guest.memory_bytes();
            let mut samples = [vec![], vec![]];
            for round in 0..11 {
                for mode in if round % 2 == 0 { [0, 1] } else { [1, 0] } {
                    let name = if mode == 0 { scalar } else { vector };
                    let start = Instant::now();
                    let actual = guest.call(name, size).unwrap();
                    let elapsed = start.elapsed().as_secs_f64() * 1000.0;
                    assert_eq!(actual, expected);
                    samples[mode].push(elapsed);
                }
            }
            let memory_after = guest.guest.memory_bytes();
            assert_eq!(memory_before, memory_after);
            let medians: Vec<_> = samples
                .iter()
                .map(|v| {
                    let mut v = v.clone();
                    v.sort_by(f64::total_cmp);
                    v[v.len() / 2]
                })
                .collect();
            println!(
                "{scalar} {size}: {:.4} -> {:.4} ms ({:.2}x)",
                medians[0],
                medians[1],
                medians[0] / medians[1]
            );
            report.push(json!({"scalar":scalar,"vector":vector,"size":size,"medianMs":medians,"samplesMs":samples,"committedMemoryBytes":memory_after,"replayGrowthBytes":memory_after-memory_before}));
        }
    }
    std::fs::write(".cache/six-more/mask-prototype.json",serde_json::to_vec_pretty(&json!({"includes":"fixture construction, guest execution and complete result decoding; alternating paired order; 5 warmups and 11 samples; complete output equality outside timings","results":report})).unwrap()).unwrap();
}

