    if tag == 0:
      if values != 0 || ready != 0 || Bool.not queue.open:
        return #Nothing
    else:
      if ready < submitted || ready > queue.tick || (Bool.not queue.open && tag != 3):
        return #Nothing
      let outcome = #Failed 0
      if tag == 1:
        let #Some value = decode_value payload else:
          return #Nothing
        outcome := #Value value
      else:
        if values != 1:
          return #Nothing
        outcome := if tag == 2 then #Failed payload[0] else #Cancelled payload[0]
      state := #Ready { tick: ready, outcome }
    out[index] := #Some (#Job { ticket: #Ticket { epoch: queue.epoch, sequence }, submitted, earliest, request, continuation: local, state })
    previous := sequence
  if offset != words.length:
    return #Nothing
  queue.jobs := array.map (fn item => case item of
    #Some job => job
    #Nothing => @panic "decoder count invariant") out
  return #Some queue
